CREATE OR REPLACE FUNCTION public.email_ingestion_account_guard_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$ begin
  if current_user='email_ingestion_protocol_owner' then return new; end if;
  if tg_op='INSERT' then
    if new.history_id is not null or new.backfill_status<>'idle' or new.backfill_started_at is not null or new.backfill_completed_at is not null or new.backfill_page_token is not null or new.backfill_total_fetched<>0 or new.backfill_error is not null then
      raise exception using errcode='42501',message='email_progress_requires_protocol';
    end if;
  elsif row(new.history_id,new.backfill_status,new.backfill_started_at,new.backfill_completed_at,new.backfill_page_token,new.backfill_total_fetched,new.backfill_error)
    is distinct from row(old.history_id,old.backfill_status,old.backfill_started_at,old.backfill_completed_at,old.backfill_page_token,old.backfill_total_fetched,old.backfill_error) then
    raise exception using errcode='42501',message='email_progress_requires_protocol';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_count_v2(v jsonb, nullable boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ begin
  if v='null'::jsonb then return nullable; end if;
  if v is null or jsonb_typeof(v)<>'number' then return false; end if;
  return (v#>>'{}')::numeric between 0 and 2147483647 and trunc((v#>>'{}')::numeric)=(v#>>'{}')::numeric;
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_evidence_v2(v jsonb, kind text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare k text; names text[]:=array['persistence','message_upsert_count','thread_upsert_count','ids_seen','gone_count','unresolved_count'];
begin
  if kind='failure' then names:=names||array['classification','coverage_complete'];
  elsif kind='release' then names:=names||array['coverage_complete'];
  elsif kind<>'success' then raise exception using errcode='22023',message='invalid_evidence'; end if;
  perform public.email_ingestion_keys_v2(v,names);
  if kind='failure' then
    if not coalesce(v->>'classification'=any(array['provider_expired','pagination_cycle','fetch_failure','parse_failure','persistence_failure','checkpoint_conflict','source_ineligible','unexpected_failure']),false)
      or not coalesce(v->>'persistence'=any(array['confirmed','unknown']),false) then
      raise exception using errcode='22023',message='invalid_evidence';
    end if;
  elsif v->>'persistence' is distinct from 'confirmed' or v->'unresolved_count' is distinct from '0'::jsonb then
    raise exception using errcode='22023',message='invalid_evidence';
  end if;
  if kind<>'success' and v->'coverage_complete' is distinct from 'false'::jsonb then raise exception using errcode='22023',message='invalid_evidence'; end if;
  foreach k in array array['message_upsert_count','thread_upsert_count','ids_seen','gone_count','unresolved_count'] loop
    if not public.email_ingestion_count_v2(v->k,kind='failure' and v->>'persistence'='unknown') then
      raise exception using errcode='22023',message='invalid_evidence';
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_payload_v2(op text, stream text, v jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare names text[]; t jsonb; k text;
begin
  case op
  when 'claim' then
    names:=array['recovery'];
    if stream='recent' and v ? 'force' then
      names:=names||array['force'];
      if jsonb_typeof(v->'force') is distinct from 'boolean' then raise exception using errcode='22023',message='invalid_force'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names);
    if v->'recovery'<>'null'::jsonb then perform public.email_ingestion_recovery_v2(v->'recovery'); end if;
  when 'initialize_traversal' then
    perform public.email_ingestion_keys_v2(v,array['captured_history_id','captured_at','page_size','query']);
    if stream<>'recent' or jsonb_typeof(v->'captured_history_id') is distinct from 'string' or
      not coalesce(v->>'captured_history_id'~'^(0|[1-9][0-9]{0,19})$',false) then raise exception using errcode='22023',message='invalid_boundary'; end if;
    if (v->>'captured_history_id')::numeric>18446744073709551615 or v->'query'<>'null'::jsonb or
      not public.email_ingestion_count_v2(v->'page_size') or (v->>'page_size')::integer not between 1 and 500 or
      not coalesce(v->>'captured_at'~'^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$',false) then raise exception using errcode='22023',message='invalid_boundary'; end if;
    perform (v->>'captured_at')::timestamptz;
  when 'checkpoint' then
    names:=array['returned_next_page_token','exhausted','page_evidence','yield_after_page'];
    if stream='recent' then names:=names||array['label','expected_input_page_token'];
    else names:=names||array['expected_page_token','expected_total','listed_count']; end if;
    perform public.email_ingestion_keys_v2(v,names);
    perform public.email_ingestion_evidence_v2(v->'page_evidence','success');
    if stream='recent' then
      if not coalesce(v->>'label'=any(array['INBOX','SENT']),false) then raise exception using errcode='22023',message='invalid_page'; end if;
      k:='expected_input_page_token';
    else
      k:='expected_page_token';
      if not public.email_ingestion_count_v2(v->'expected_total') or not public.email_ingestion_count_v2(v->'listed_count') then raise exception using errcode='22023',message='invalid_page'; end if;
    end if;
    foreach t in array array[v->k,v->'returned_next_page_token'] loop
      if t<>'null'::jsonb and (jsonb_typeof(t)<>'string' or length(t#>>'{}') not between 1 and 8192) then raise exception using errcode='22023',message='invalid_token'; end if;
    end loop;
    if jsonb_typeof(v->'exhausted')<>'boolean' or jsonb_typeof(v->'yield_after_page')<>'boolean' or
      (v->>'exhausted')::boolean is distinct from (v->'returned_next_page_token'='null'::jsonb) then raise exception using errcode='22023',message='invalid_page'; end if;
  when 'release' then
    perform public.email_ingestion_keys_v2(v,array['reason_code','attempt_evidence']);
    if not coalesce(v->>'reason_code'=any(array['page_budget','time_budget','requested_yield']),false) then raise exception using errcode='22023',message='invalid_release'; end if;
    perform public.email_ingestion_evidence_v2(v->'attempt_evidence','release');
  when 'block','finish_attempt' then
    names:=array['error_code','attempt_evidence'];
    if op='finish_attempt' then names:=names||array['outcome'];
      if not coalesce(v->>'outcome'=any(array['failed','superseded']),false) then raise exception using errcode='22023',message='invalid_outcome'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names);
    if not coalesce(v->>'error_code'=any(array['history_expired','continuation_expired','pagination_no_progress','fetch_failed','parse_failed','persistence_failed','checkpoint_conflict','source_ineligible','unexpected_failure']),false) then raise exception using errcode='22023',message='invalid_error'; end if;
    perform public.email_ingestion_evidence_v2(v->'attempt_evidence','failure');
  when 'takeover' then
    perform public.email_ingestion_keys_v2(v,array['recovery']); perform public.email_ingestion_recovery_v2(v->'recovery');
  when 'restart' then
    names:=array['reason_code','recovery'];
    if stream='recent' and v ? 'fetch_policy' then
      names:=names||array['fetch_policy'];
      if not coalesce(v->>'fetch_policy'=any(array['missing_only','refetch_all']),false) then raise exception using errcode='22023',message='invalid_fetch_policy'; end if;
    end if;
    perform public.email_ingestion_keys_v2(v,names); perform public.email_ingestion_recovery_v2(v->'recovery');
    if not coalesce(v->>'reason_code'=any(array['operator_restart','history_expired','continuation_expired']),false) then raise exception using errcode='22023',message='invalid_restart'; end if;
  else raise exception using errcode='22023',message='invalid_operation';
  end case;
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_run_guard_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare protected boolean;
begin
  if tg_op='INSERT' then
    if new.sync_type in ('messages','workspace_messages','workspace_backfill') then
      if new.status<>'running' or new.completed_at is not null or new.records_processed<>0 or
        jsonb_typeof(new.metadata->'email_account_id') is distinct from 'string' or
        not coalesce(new.metadata->>'email_account_id'~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false) or new.metadata ? 'email_ingestion_v2' then
        raise exception using errcode='42501',message='invalid_ingestion_attempt';
      end if;
    end if;
    return new;
  end if;
  protected:=old.sync_type in ('messages','workspace_messages','workspace_backfill');
  if tg_op='UPDATE' then protected:=protected or new.sync_type in ('messages','workspace_messages','workspace_backfill'); end if;
  if not protected then if tg_op='DELETE' then return old; else return new; end if; end if;
  if tg_op='DELETE' or current_user<>'email_ingestion_protocol_owner' then
    raise exception using errcode='42501',message='email_attempt_requires_protocol';
  end if;
  if row(new.id,new.tenant_id,new.provider,new.sync_type,new.started_at,new.metadata->'email_account_id') is distinct from
     row(old.id,old.tenant_id,old.provider,old.sync_type,old.started_at,old.metadata->'email_account_id') then
    raise exception using errcode='42501',message='immutable_ingestion_attempt';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_transition_result_v2(p_tenant_id uuid, p_email_account_id uuid, p_stream text, p_attempt_id uuid, p_transition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.email_ingestion_checkpoints%rowtype; r public.email_ingestion_transitions%rowtype;
 a public.email_sync_runs%rowtype; has_receipt boolean;
begin
 if p_tenant_id is null or p_email_account_id is null or p_attempt_id is null or p_transition_id is null or p_stream is null or p_stream not in ('recent','historical') then
   raise exception using errcode='22023',message='invalid_request';
 end if;
 perform 1 from public.email_accounts where tenant_id=p_tenant_id and id=p_email_account_id and provider='gmail' for update;
 if not found then raise exception using errcode='42501',message='account_not_found'; end if;
 perform 1 from public.email_ingestion_checkpoints where tenant_id=p_tenant_id and email_account_id=p_email_account_id
   order by case stream when 'recent' then 0 else 1 end for update;
 select * into c from public.email_ingestion_checkpoints where tenant_id=p_tenant_id and email_account_id=p_email_account_id and stream=p_stream;
 select * into r from public.email_ingestion_transitions where tenant_id=p_tenant_id and email_account_id=p_email_account_id and stream=p_stream and transition_id=p_transition_id;
 has_receipt:=found;
 select * into a from public.email_sync_runs where tenant_id=p_tenant_id and id=p_attempt_id for update;
 if not found or a.provider<>'gmail' or jsonb_typeof(a.metadata->'email_account_id') is distinct from 'string' or
   not coalesce(a.metadata->>'email_account_id'~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false) then
   raise exception using errcode='42501',message='attempt_mismatch';
 end if;
 if (a.metadata->>'email_account_id')::uuid<>p_email_account_id or
   (p_stream='historical' and a.sync_type<>'workspace_backfill') or (p_stream='recent' and a.sync_type not in ('messages','workspace_messages')) or
   (has_receipt and r.attempt_id<>p_attempt_id) or
   exists(select 1 from public.email_ingestion_transitions where attempt_id=p_attempt_id and
     (tenant_id<>p_tenant_id or email_account_id<>p_email_account_id or stream<>p_stream)) then raise exception using errcode='42501',message='attempt_mismatch'; end if;
 -- Terminal attempts and subsequently disabled sources can still inspect their receipts.
 return jsonb_build_object('contract_version',2,'disposition',case when has_receipt then 'replayed' else 'conflict' end,
   'code',case when has_receipt then 'receipt_replayed' else 'not_found' end,'transition_id',p_transition_id,
   'accepted_result',case when has_receipt then r.accepted_result else null end,
   'current_checkpoint',public.email_ingestion_checkpoint_json_v2(c),'historical_receipt',has_receipt);
end $function$

CREATE OR REPLACE FUNCTION public.email_ingestion_transition_v2(p_tenant_id uuid, p_email_account_id uuid, p_stream text, p_attempt_id uuid, p_transition_id uuid, p_operation text, p_expected_generation uuid, p_expected_revision bigint, p_expected_owner_attempt_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
 a record; c public.email_ingestion_checkpoints%rowtype; receipt public.email_ingestion_transitions%rowtype;
 attempt public.email_sync_runs%rowtype; doc jsonb; result jsonb; evidence jsonb;
 exists_checkpoint boolean; replay boolean; changed boolean:=true; eligible boolean;
 done boolean:=false; terminal boolean:=false; attempt_status text:='running'; error_code text;
 records integer; label text; input_token text; next_token text; mode text; current_cursor text;
 new_total bigint; code text; v_attempt_metadata jsonb; confirmed_count integer; v_fetch_policy text; v_force boolean;
begin
 if p_tenant_id is null or p_email_account_id is null or p_attempt_id is null or p_transition_id is null or
   p_stream is null or p_stream not in ('recent','historical') or p_operation is null or
   p_expected_revision<0 then raise exception using errcode='22023',message='invalid_request'; end if;
 perform public.email_ingestion_payload_v2(p_operation,p_stream,p_payload);
 -- Defaults do not rewrite the frozen request_document: omitted/false remain
 -- different requests for same-ID replay equality, even when semantically equal.
 v_force:=p_stream='recent' and p_operation='claim' and coalesce((p_payload->>'force')::boolean,false);
 -- No whole account SELECT: this role has no token, identity-write or authority privileges.
 select id,tenant_id,provider,status,auth_state,history_id,backfill_status,backfill_started_at,
   backfill_completed_at,backfill_page_token,backfill_total_fetched,backfill_error
 into a from public.email_accounts where tenant_id=p_tenant_id and id=p_email_account_id and provider='gmail' for update;
 if not found then raise exception using errcode='P0001',message='account_not_found'; end if;
 perform 1 from public.email_ingestion_checkpoints where tenant_id=p_tenant_id and email_account_id=p_email_account_id
   order by case stream when 'recent' then 0 else 1 end for update;
 select * into c from public.email_ingestion_checkpoints where tenant_id=p_tenant_id and email_account_id=p_email_account_id and stream=p_stream;
 exists_checkpoint:=found;
 select * into receipt from public.email_ingestion_transitions where tenant_id=p_tenant_id and email_account_id=p_email_account_id and stream=p_stream and transition_id=p_transition_id;
 replay:=found;
 -- Own attempt lock comes BEFORE mutable status/association validation and mutation.
 select * into attempt from public.email_sync_runs where id=p_attempt_id and tenant_id=p_tenant_id for update;
 if not found or attempt.provider<>'gmail' or jsonb_typeof(attempt.metadata->'email_account_id') is distinct from 'string' or
   not coalesce(attempt.metadata->>'email_account_id'~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false) then
   raise exception using errcode='P0001',message='attempt_mismatch';
 end if;
 if (attempt.metadata->>'email_account_id')::uuid<>p_email_account_id or
   (p_stream='historical' and attempt.sync_type<>'workspace_backfill') or
   (p_stream='recent' and attempt.sync_type not in ('messages','workspace_messages')) or
   exists(select 1 from public.email_ingestion_transitions where attempt_id=p_attempt_id and
     (tenant_id<>p_tenant_id or email_account_id<>p_email_account_id or stream<>p_stream)) or
   exists(select 1 from public.email_ingestion_checkpoints where owner_attempt_id=p_attempt_id and
     (tenant_id<>p_tenant_id or email_account_id<>p_email_account_id or stream<>p_stream)) then
   raise exception using errcode='P0001',message='attempt_mismatch';
 end if;
 doc:=jsonb_build_object('tenant_id',p_tenant_id,'email_account_id',p_email_account_id,'stream',p_stream,
   'attempt_id',p_attempt_id,'transition_id',p_transition_id,'operation',p_operation,
   'expected_generation',p_expected_generation,'expected_revision',p_expected_revision::text,
   'expected_owner_attempt_id',p_expected_owner_attempt_id,'payload',p_payload);
 if replay then
   if receipt.attempt_id<>p_attempt_id or receipt.request_document<>doc then raise exception using errcode='P0001',message='transition_id_reused'; end if;
   return jsonb_build_object('contract_version',2,'disposition','replayed','code','receipt_replayed','transition_id',p_transition_id,
     'accepted_result',receipt.accepted_result,'current_checkpoint',public.email_ingestion_checkpoint_json_v2(c),'historical_receipt',true);
 end if;
 if attempt.status<>'running' then raise exception using errcode='P0001',message='attempt_terminal'; end if;
 records:=attempt.records_processed;
 -- Slice A account check ONLY; DWD relationship/revision locking is not claimed.
 eligible:=case when attempt.sync_type='messages' then a.status='active' and a.auth_state in ('ok','unknown')
   else a.status in ('pending_tokenless_dwd','active_dwd') end;
 if p_operation not in ('block','release','finish_attempt') and not eligible then raise exception using errcode='P0001',message='source_ineligible'; end if;
 if p_operation='finish_attempt' then
   if exists_checkpoint and c.owner_attempt_id=p_attempt_id then raise exception using errcode='P0001',message='owner_must_release'; end if;
   if not exists_checkpoint and (p_expected_generation is not null or p_expected_revision is not null or p_expected_owner_attempt_id is not null) then
     raise exception using errcode='22023',message='absent_checkpoint_requires_null_fences';
   end if;
   -- Explicit stale-version exception: only caller's own evidence; no progress update.
   changed:=false; terminal:=true; attempt_status:='failed'; error_code:=p_payload->>'error_code';
   evidence:=p_payload->'attempt_evidence';
 else
   if not exists_checkpoint then
     if p_operation<>'claim' or p_expected_generation is not null or p_expected_revision is not null or p_expected_owner_attempt_id is not null or p_payload->'recovery'<>'null'::jsonb then
       raise exception using errcode='P0001',message='checkpoint_missing';
     end if;
     c.tenant_id:=p_tenant_id; c.email_account_id:=p_email_account_id; c.stream:=p_stream; c.contract_version:=2;
     c.generation:=gen_random_uuid(); c.revision:=0; c.state:='ready'; c.owner_attempt_id:=null;
     c.created_at:=now(); c.updated_at:=now();
     if p_stream='recent' then c.continuation:=jsonb_build_object('version',2,'phase','uninitialized',
       'intent',case when v_force then 'reconcile' else 'normal' end,
       'fetch_policy',case when v_force then 'refetch_all' else 'missing_only' end);
     elsif a.backfill_status='completed' then c.state:='completed';
     elsif a.backfill_status='error' then
       c.state:='blocked';
       -- Preserve recognised classifications, especially restart-only expiry.
       -- Unknown legacy error text must not leak into protocol evidence.
       c.block_code:=case when a.backfill_error in (
         'history_expired','continuation_expired','pagination_no_progress',
         'fetch_failed','parse_failed','persistence_failed','checkpoint_conflict',
         'source_ineligible','unexpected_failure') then a.backfill_error else 'unexpected_failure' end;
     elsif a.backfill_status not in ('idle','running') then raise exception using errcode='P0001',message='legacy_state_invalid'; end if;
   elsif c.generation is distinct from p_expected_generation or c.revision is distinct from p_expected_revision or c.owner_attempt_id is distinct from p_expected_owner_attempt_id then
     raise exception using errcode='P0001',message='checkpoint_conflict';
   end if;
   if p_stream='recent' and p_operation<>'restart' then
     -- Known pre-policy generations were missing-only. Materialize only an
     -- absent field, never coalesce explicit null/invalid policy into permission.
     if jsonb_typeof(c.continuation) is distinct from 'object' then raise exception using errcode='P0001',message='invalid_legacy_policy'; end if;
     if not (c.continuation ? 'fetch_policy') then c.continuation:=c.continuation||jsonb_build_object('fetch_policy','missing_only'); end if;
     v_fetch_policy:=c.continuation->>'fetch_policy';
     if not coalesce(v_fetch_policy=any(array['missing_only','refetch_all']),false) or
       (v_fetch_policy='refetch_all' and not coalesce(
         (c.continuation->>'phase'='uninitialized' and c.continuation->>'intent'='reconcile') or
         (c.continuation->>'phase'='initialized' and c.continuation->>'mode'='reconcile'),false)) then
       raise exception using errcode='P0001',message='invalid_legacy_policy';
     end if;
   end if;
   case p_operation
   when 'claim' then
     if p_stream='recent' and exists_checkpoint and c.state<>'completed' and v_force and v_fetch_policy<>'refetch_all' then
       raise exception using errcode='P0001',message='force_generation_busy';
     end if;
     if not exists_checkpoint and c.state in ('completed','blocked') then
       terminal:=true; done:=c.state='completed'; attempt_status:=case when done then 'success' else 'failed' end;
       error_code:=case when done then null else c.block_code end;
     elsif p_stream='historical' and c.state='completed' then
       if p_payload->'recovery'<>'null'::jsonb then raise exception using errcode='P0001',message='invalid_recovery_state'; end if;
       changed:=false; done:=true; terminal:=true; attempt_status:='success';
     else
       if c.state='blocked' then
         if p_payload->'recovery'='null'::jsonb or c.block_code in ('history_expired','continuation_expired') then
           raise exception using errcode='P0001',message='explicit_recovery_required';
         end if;
       elsif p_payload->'recovery'<>'null'::jsonb then raise exception using errcode='P0001',message='invalid_recovery_state';
       elsif c.state<>'ready' and not(p_stream='recent' and c.state='completed') then raise exception using errcode='P0001',message='already_claimed'; end if;
       if p_stream='recent' and c.state='completed' then
         c.generation:=gen_random_uuid(); c.continuation:=jsonb_build_object('version',2,'phase','uninitialized',
           'intent',case when v_force then 'reconcile' else 'normal' end,
           'fetch_policy',case when v_force then 'refetch_all' else 'missing_only' end);
       end if;
       c.state:='claimed'; c.owner_attempt_id:=p_attempt_id; c.block_code:=null;
       if p_stream='historical' then
         update public.email_accounts set backfill_status='running',backfill_error=null,
           backfill_started_at=case when backfill_status='idle' and backfill_started_at is null then now() else backfill_started_at end
           where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if;
       end if;
     end if;
   when 'takeover' then
     if c.state<>'claimed' or c.owner_attempt_id=p_attempt_id then raise exception using errcode='P0001',message='invalid_recovery_state'; end if;
     c.owner_attempt_id:=p_attempt_id;
     if p_stream='historical' then update public.email_accounts set backfill_status='running',backfill_error=null where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if; end if;
   when 'restart' then
     c.generation:=gen_random_uuid(); c.state:='claimed'; c.owner_attempt_id:=p_attempt_id; c.block_code:=null;
     if p_stream='recent' then c.continuation:=jsonb_build_object('version',2,'phase','uninitialized','intent','reconcile',
       'fetch_policy',coalesce(p_payload->>'fetch_policy','missing_only'));
     else update public.email_accounts set backfill_status='running',backfill_page_token=null,backfill_total_fetched=0,
       backfill_started_at=now(),backfill_completed_at=null,backfill_error=null where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if; end if;
   else
     if c.state<>'claimed' or c.owner_attempt_id is distinct from p_attempt_id then raise exception using errcode='P0001',message='not_owner'; end if;
     case p_operation
     when 'initialize_traversal' then
       if c.continuation->>'phase' is distinct from 'uninitialized' then raise exception using errcode='P0001',message='already_initialized'; end if;
       current_cursor:=a.history_id;
       if current_cursor is not null then
         if current_cursor!~'^(0|[1-9][0-9]{0,19})$' then raise exception using errcode='P0001',message='invalid_legacy_cursor'; end if;
         if current_cursor::numeric>18446744073709551615 or (p_payload->>'captured_history_id')::numeric<current_cursor::numeric then raise exception using errcode='P0001',message='boundary_regression'; end if;
       end if;
       mode:=case when c.continuation->>'intent'='normal' and current_cursor is not null then 'history' else 'reconcile' end;
       c.continuation:=jsonb_build_object('version',2,'phase','initialized','mode',mode,'origin_history_id',current_cursor,
         'fetch_policy',c.continuation->>'fetch_policy',
         'captured_history_id',p_payload->>'captured_history_id','captured_at',p_payload->>'captured_at',
         'page_size',p_payload->'page_size','query',null,'labels',jsonb_build_array('INBOX','SENT'),
         'labels_state',jsonb_build_object('INBOX',jsonb_build_object('next_page_token',null,'complete',false),
           'SENT',jsonb_build_object('next_page_token',null,'complete',false)));
     when 'checkpoint' then
       next_token:=p_payload->>'returned_next_page_token'; evidence:=p_payload->'page_evidence';
       if p_stream='recent' then
         label:=p_payload->>'label'; input_token:=p_payload->>'expected_input_page_token';
         if c.continuation->>'phase' is distinct from 'initialized' then raise exception using errcode='P0001',message='not_initialized'; end if;
         if c.continuation#>>array['labels_state',label,'complete'] is distinct from 'false' or
           c.continuation#>>array['labels_state',label,'next_page_token'] is distinct from input_token then raise exception using errcode='P0001',message='page_conflict'; end if;
         if a.history_id is distinct from c.continuation->>'origin_history_id' then raise exception using errcode='P0001',message='cursor_conflict'; end if;
       else
         label:=null; input_token:=p_payload->>'expected_page_token';
         if a.backfill_status<>'running' or a.backfill_page_token is distinct from input_token or a.backfill_total_fetched<>(p_payload->>'expected_total')::integer then raise exception using errcode='P0001',message='page_conflict'; end if;
       end if;
       if next_token is not null and (next_token is not distinct from input_token or exists(
         select 1 from public.email_ingestion_transitions t where t.tenant_id=p_tenant_id and t.email_account_id=p_email_account_id
           and t.stream=p_stream and t.result_generation=c.generation and t.operation='checkpoint'
           and (t.request_document->'payload'->>'label') is not distinct from label
           and ((md5(coalesce(t.request_document->'payload'->>'expected_input_page_token',t.request_document->'payload'->>'expected_page_token'))=md5(next_token)
             and coalesce(t.request_document->'payload'->>'expected_input_page_token',t.request_document->'payload'->>'expected_page_token')=next_token)
           or (md5(t.request_document->'payload'->>'returned_next_page_token')=md5(next_token) and t.request_document->'payload'->>'returned_next_page_token'=next_token))
       )) then raise exception using errcode='P0001',message='pagination_no_progress'; end if;
       if p_stream='recent' then
         c.continuation:=jsonb_set(c.continuation,array['labels_state',label],jsonb_build_object('next_page_token',next_token,'complete',(p_payload->>'exhausted')::boolean));
         done:=(c.continuation#>>'{labels_state,INBOX,complete}')::boolean and (c.continuation#>>'{labels_state,SENT,complete}')::boolean;
         if done then update public.email_accounts set history_id=c.continuation->>'captured_history_id' where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if; end if;
       else
         new_total:=a.backfill_total_fetched::bigint+(p_payload->>'listed_count')::bigint;
         if new_total>2147483647 then raise exception using errcode='P0001',message='total_overflow'; end if;
         done:=(p_payload->>'exhausted')::boolean;
         update public.email_accounts set backfill_page_token=next_token,backfill_total_fetched=new_total::integer,
           backfill_status=case when done then 'completed' else 'running' end,
           backfill_completed_at=case when done then now() else null end,backfill_error=null
           where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if;
       end if;
       new_total:=records::bigint+(evidence->>'message_upsert_count')::bigint;
       if new_total>2147483647 then raise exception using errcode='P0001',message='total_overflow'; end if;
       records:=new_total::integer;
       if done or (p_payload->>'yield_after_page')::boolean then
         c.state:=case when done then 'completed' else 'ready' end; c.owner_attempt_id:=null; terminal:=true; attempt_status:='success';
       end if;
     when 'release' then
       c.state:='ready'; c.owner_attempt_id:=null; terminal:=true; attempt_status:='success'; evidence:=p_payload->'attempt_evidence';
     when 'block' then
       c.state:='blocked'; c.owner_attempt_id:=null; c.block_code:=p_payload->>'error_code';
       terminal:=true; attempt_status:='failed'; error_code:=c.block_code; evidence:=p_payload->'attempt_evidence';
       if p_stream='historical' then update public.email_accounts set backfill_status='error',backfill_error=c.block_code where tenant_id=p_tenant_id and id=p_email_account_id;
         if not found then raise exception 'account progress update affected no row'; end if; end if;
     else raise exception using errcode='22023',message='invalid_operation';
     end case;
   end case;
 end if;
 if changed then
   if c.revision=9223372036854775807 then raise exception using errcode='P0001',message='revision_exhausted'; end if;
   c.revision:=c.revision+1; c.updated_at:=now();
   if not exists_checkpoint then
     insert into public.email_ingestion_checkpoints(tenant_id,email_account_id,stream,contract_version,generation,revision,state,owner_attempt_id,continuation,block_code,created_at,updated_at)
     values(c.tenant_id,c.email_account_id,c.stream,c.contract_version,c.generation,c.revision,c.state,c.owner_attempt_id,c.continuation,c.block_code,c.created_at,c.updated_at);
   else
     update public.email_ingestion_checkpoints set generation=c.generation,revision=c.revision,state=c.state,
       owner_attempt_id=c.owner_attempt_id,continuation=c.continuation,block_code=c.block_code,updated_at=c.updated_at
       where tenant_id=p_tenant_id and email_account_id=p_email_account_id and stream=p_stream;
     if not found then raise exception 'checkpoint update affected no row'; end if;
   end if;
 end if;
 if p_operation in ('block','release','finish_attempt') then
   -- These counts are attempt-wide known totals; NULL never overwrites with zero.
   confirmed_count:=(evidence->>'message_upsert_count')::integer;
   if confirmed_count is not null then
     if confirmed_count<records then raise exception using errcode='22023',message='count_regression'; end if;
     records:=confirmed_count;
   end if;
 end if;
 result:=jsonb_build_object('operation',p_operation,'attempt_id',p_attempt_id,'tenant_id',p_tenant_id,'email_account_id',p_email_account_id,'stream',p_stream,
   'checkpoint_present',c.tenant_id is not null,'generation',c.generation,'revision',c.revision::text,
   'checkpoint_state',c.state,'owner_attempt_id',c.owner_attempt_id,'attempt_status',attempt_status,
   'records_processed',records,'coverage_complete',done);
 insert into public.email_ingestion_transitions(tenant_id,email_account_id,stream,transition_id,operation,attempt_id,
   expected_generation,expected_revision,expected_owner_attempt_id,request_document,request_fingerprint,accepted_result,checkpoint_stream,result_generation,result_revision)
 values(p_tenant_id,p_email_account_id,p_stream,p_transition_id,p_operation,p_attempt_id,p_expected_generation,p_expected_revision,
   p_expected_owner_attempt_id,doc,md5(doc::text),result,case when c.tenant_id is not null then p_stream else null end,c.generation,c.revision);
 v_attempt_metadata:=attempt.metadata||jsonb_build_object('email_ingestion_v2',jsonb_build_object('contract_version',2,'stream',p_stream,
   'transition_id',p_transition_id,'operation',p_operation,'checkpoint_present',c.tenant_id is not null,'generation',c.generation,'revision',c.revision::text,
   'coverage_complete',done,'continuation_pending',c.state<>'completed','evidence',evidence,
   'classification',case when p_operation='finish_attempt' then p_payload->>'outcome' else null end));
 update public.email_sync_runs as target_run set status=attempt_status,completed_at=case when terminal then now() else null end,
   records_processed=records,error_message=error_code,metadata=v_attempt_metadata
   where target_run.id=p_attempt_id and target_run.tenant_id=p_tenant_id and target_run.status='running';
 if not found then raise exception 'attempt update disappeared'; end if;
 return jsonb_build_object('contract_version',2,'disposition','applied','code','transition_applied','transition_id',p_transition_id,
   'accepted_result',result,'current_checkpoint',public.email_ingestion_checkpoint_json_v2(c),'historical_receipt',false);
exception
 when invalid_parameter_value or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
   return jsonb_build_object('contract_version',2,'disposition','denied','code','invalid_request','transition_id',p_transition_id,'accepted_result',null,'current_checkpoint',null,'historical_receipt',false);
 when sqlstate 'P0001' then
   code:=sqlerrm;
   if code<>all(array['account_not_found','attempt_mismatch','transition_id_reused','attempt_terminal','source_ineligible','owner_must_release',
     'checkpoint_missing','legacy_state_invalid','checkpoint_conflict','invalid_recovery_state','explicit_recovery_required','already_claimed',
     'not_owner','already_initialized','invalid_legacy_cursor','boundary_regression','not_initialized','page_conflict','cursor_conflict',
     'pagination_no_progress','total_overflow','revision_exhausted','force_generation_busy','invalid_legacy_policy']) then raise; end if;
   -- Exception subtransaction rolled back ALL writes; never return staged c as current.
   return jsonb_build_object('contract_version',2,'disposition',case when code in ('account_not_found','attempt_mismatch','transition_id_reused','source_ineligible') then 'denied' else 'conflict' end,
     'code',code,'transition_id',p_transition_id,'accepted_result',null,'current_checkpoint',null,'historical_receipt',false);
end $function$

CREATE OR REPLACE FUNCTION public.learn_capture_admission(p_tenant uuid, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare allowed boolean;begin
 if current_user<>'service_role' then raise exception 'learn_capture_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'learn_capture_snapshot_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 allowed:=public.learn_capture_allowed(p_tenant,p_source);
 return jsonb_build_object('version','learn-capture-admission/1','tenant_id',p_tenant,'source',p_source,'allowed',allowed,'checked_at',clock_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.learn_capture_defer_job(p_tenant uuid, p_job uuid, p_claimed_by text, p_attempt integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;prior jsonb;answer jsonb;begin
 if current_user<>'service_role' then raise exception 'learn_capture_forbidden' using errcode='42501';end if;
 if p_reason is null or p_reason not in ('paused','unavailable') or p_attempt is null or p_attempt<1 or nullif(p_claimed_by,'') is null then
  raise exception 'learn_capture_defer_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where id=p_job and tenant_id=p_tenant for update;
 if not found or j.job_type not in ('email.gmail_sync','email.workspace_sync','email.workspace_backfill','email.mailbox_discovery','slack.history_sync','slack.thread_sync') then
  raise exception 'learn_capture_defer_not_owned' using errcode='PT409';end if;
 prior:=j.metadata->'learn_capture_deferred_v1';
 if prior->>'claimed_by'=p_claimed_by and prior->>'attempt'=p_attempt::text then
  if prior->>'reason' is distinct from p_reason then raise exception 'learn_capture_defer_conflict' using errcode='PT409';end if;
  return prior->'answer';
 end if;
 if j.status<>'running' or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_attempt
  or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp() or coalesce(j.metadata,'{}') ? 'slack_page_v1' then
  raise exception 'learn_capture_defer_not_owned' using errcode='PT409';end if;
 answer:=jsonb_build_object('job_id',p_job,'state','waiting','reason',p_reason,'attempt_count',p_attempt-1);
 update public.platform_jobs set status='queued',claimed_by=null,claimed_at=null,lease_expires_at=null,
  attempt_count=p_attempt-1,available_at=clock_timestamp()+interval '60 seconds',
  metadata=coalesce(metadata,'{}')||jsonb_build_object('learn_capture_deferred_v1',jsonb_build_object('claimed_by',p_claimed_by,'attempt',p_attempt,'reason',p_reason,'answer',answer)) where id=j.id;
 if j.job_type in ('slack.history_sync','slack.thread_sync') then
  update public.slack_workspace_pacing set active_job_id=null,last_finished_at=clock_timestamp(),
   next_allowed_at=greatest(blocked_until,clock_timestamp()+interval '60 seconds') where active_job_id=j.id;
 end if;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_attempt_lease(p_attempt uuid, p_claimed_by text, p_claim integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare j public.platform_jobs%rowtype;b public.learn_email_job_attempts%rowtype;begin
 if current_user<>'service_role' then raise exception 'learn_email_job_forbidden' using errcode='42501';end if;
 select * into b from public.learn_email_job_attempts where attempt_id=p_attempt;
 if not found then
  if p_claimed_by is not null or p_claim is not null then raise exception 'learn_email_job_binding_missing' using errcode='PT409';end if;
  return;
 end if;
 select * into j from public.platform_jobs where id=b.job_id and tenant_id=b.tenant_id for update;
 if not found or j.status<>'running' or nullif(p_claimed_by,'') is null or p_claim is null
  or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_claim
  or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp()
  or b.definition is distinct from jsonb_build_object('job_type',j.job_type,'job_key',j.job_key,'payload',j.payload,'connector_id',j.connector_id,'module_id',j.module_id)
 then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_enqueue(p_tenant uuid, p_account uuid, p_type text, p_options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.email_accounts%rowtype;j public.platform_jobs%rowtype;
 payload jsonb;connector text;key text;duplicate boolean;n integer;begin
 if current_user<>'service_role' then raise exception 'learn_email_enqueue_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_account is null or p_type is null or p_type not in ('email.gmail_sync','email.workspace_sync','email.workspace_backfill')
  or jsonb_typeof(p_options) is distinct from 'object' or (p_options-array['max_results','force','restart'])<>'{}'::jsonb then
  raise exception 'learn_email_enqueue_invalid' using errcode='22023';end if;
 if (p_options ? 'force' and jsonb_typeof(p_options->'force') is distinct from 'boolean')
  or (p_options ? 'restart' and jsonb_typeof(p_options->'restart') is distinct from 'boolean')
  or (p_type='email.workspace_backfill' and p_options ? 'force')
  or (p_type<>'email.workspace_backfill' and p_options ? 'restart') then
  raise exception 'learn_email_enqueue_invalid' using errcode='22023';end if;
 if p_options ? 'max_results' then
  if jsonb_typeof(p_options->'max_results') is distinct from 'number' or not coalesce(p_options->>'max_results'~'^[0-9]{1,3}$',false) then
   raise exception 'learn_email_enqueue_invalid' using errcode='22023';end if;
  if (p_options->>'max_results')::integer not between 1 and 500 then raise exception 'learn_email_enqueue_invalid' using errcode='22023';end if;
 end if;
 if p_options->'restart'='true'::jsonb then raise exception 'learn_email_explicit_recovery_required' using errcode='PT409';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'learn_capture_snapshot_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 if not public.learn_capture_allowed(p_tenant,'email') then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 select * into a from public.email_accounts where id=p_account and tenant_id=p_tenant and provider='gmail';
 if not found or (p_type='email.gmail_sync' and (a.status<>'active' or a.auth_state not in ('ok','unknown') or a.auth_state is null))
  or (p_type<>'email.gmail_sync' and a.status not in ('pending_tokenless_dwd','active_dwd')) then
  raise exception 'learn_email_source_ineligible' using errcode='PT409';end if;
 -- The worker rechecks all current mailbox/connection authority before tokens.
 payload:=jsonb_build_object('email_account_id',p_account);
 if p_type<>'email.workspace_backfill' or p_options ? 'max_results' then
  payload:=payload||jsonb_build_object('max_results',coalesce((p_options->>'max_results')::integer,25));end if;
 if p_options->'force'='true'::jsonb then payload:=payload||'{"force":true}'::jsonb;end if;
 connector:=case when p_type='email.gmail_sync' then 'gmail' else 'google-workspace' end;
 key:=p_type||':'||p_account::text;
 -- The unique active-job key arbitrates concurrent schedulers and requests.
 -- Never overwrite an existing payload, including a different rescan intent.
 for n in 1..3 loop
  insert into public.platform_jobs(tenant_id,connector_id,module_id,job_type,job_key,priority,max_attempts,payload)
   values(p_tenant,connector,'communications.email',p_type,key,case when p_type='email.workspace_backfill' then 200 else 100 end,5,payload)
   on conflict(tenant_id,job_key) where job_key is not null and status in ('queued','running','retrying') do nothing returning * into j;
  duplicate:=not found;
  if duplicate then
   select * into j from public.platform_jobs where tenant_id=p_tenant and job_key=key and status in ('queued','running','retrying') for share;
   if not found then continue;end if;
   if j.job_type is distinct from p_type or j.connector_id is distinct from connector or j.module_id is distinct from 'communications.email' or j.payload is distinct from payload then
    raise exception 'learn_email_active_request_conflict' using errcode='PT409';end if;
  end if;
  return jsonb_build_object('version','learn-email-enqueue/1','success',true,'state','queued','job_id',j.id,'duplicate',duplicate,'provider','gmail','email_account_id',p_account);
 end loop;
 raise exception 'learn_email_enqueue_busy' using errcode='PT409';
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_job_attempt(p_tenant uuid, p_job uuid, p_claimed_by text, p_claim integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;b public.learn_email_job_attempts%rowtype;run public.email_sync_runs%rowtype;
 account uuid;kind text;stream_name text;definition jsonb;recovered boolean;begin
 if current_user<>'service_role' then raise exception 'learn_email_job_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_job is null or nullif(p_claimed_by,'') is null or p_claim is null or p_claim<1 then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where tenant_id=p_tenant and id=p_job for update;
 if not found or j.status<>'running' or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_claim
  or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp() then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 if j.job_type not in ('email.gmail_sync','email.workspace_sync','email.workspace_backfill')
  or jsonb_typeof(j.payload) is distinct from 'object' or octet_length(j.payload::text)>4000
  or jsonb_typeof(j.payload->'email_account_id') is distinct from 'string'
  or not coalesce(j.payload->>'email_account_id'~*'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$',false)
  or (j.payload-array['email_account_id','max_results','force','restart'])<>'{}'::jsonb then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 if j.payload ? 'max_results' then
  if jsonb_typeof(j.payload->'max_results') is distinct from 'number' or not coalesce(j.payload->>'max_results'~'^[0-9]{1,3}$',false) then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
  if (j.payload->>'max_results')::integer not between 1 and 500 then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 end if;
 if (j.payload ? 'force' and jsonb_typeof(j.payload->'force') is distinct from 'boolean')
  or (j.payload ? 'restart' and jsonb_typeof(j.payload->'restart') is distinct from 'boolean') then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 account:=(j.payload->>'email_account_id')::uuid;
 if j.job_key is distinct from j.job_type||':'||(j.payload->>'email_account_id') then raise exception 'learn_email_job_identity' using errcode='22023';end if;
 perform 1 from public.email_accounts where id=account and tenant_id=p_tenant and provider='gmail';
 if not found then raise exception 'learn_email_job_identity' using errcode='42501';end if;
 kind:=case j.job_type when 'email.gmail_sync' then 'messages' when 'email.workspace_sync' then 'workspace_messages' else 'workspace_backfill' end;
 stream_name:=case when j.job_type='email.workspace_backfill' then 'historical' else 'recent' end;
 definition:=jsonb_build_object('job_type',j.job_type,'job_key',j.job_key,'payload',j.payload,'connector_id',j.connector_id,'module_id',j.module_id);
 select * into b from public.learn_email_job_attempts where job_id=j.id;
 recovered:=found;
 if recovered then
  if b.tenant_id<>p_tenant or b.email_account_id<>account or b.stream<>stream_name or b.sync_type<>kind or b.definition<>definition then raise exception 'learn_email_job_definition_changed' using errcode='PT409';end if;
 else
  b.attempt_id:=gen_random_uuid();
  insert into public.email_sync_runs(id,tenant_id,provider,sync_type,status,metadata)
   values(b.attempt_id,p_tenant,'gmail',kind,'running',jsonb_build_object('email_account_id',account,'learn_email_job_id',j.id));
  insert into public.learn_email_job_attempts(job_id,tenant_id,email_account_id,attempt_id,stream,sync_type,definition)
   values(j.id,p_tenant,account,b.attempt_id,stream_name,kind,definition);
 end if;
 select * into run from public.email_sync_runs where id=b.attempt_id and tenant_id=p_tenant;
 if not found or run.provider<>'gmail' or run.sync_type<>kind or run.status not in ('running','success','failed')
  or (run.metadata->>'email_account_id')::uuid is distinct from account then raise exception 'learn_email_job_attempt_mismatch' using errcode='PT409';end if;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 return jsonb_build_object('version','learn-email-job-attempt/1','tenant_id',p_tenant,'job_id',j.id,'email_account_id',account,
  'attempt_id',b.attempt_id,'stream',stream_name,'sync_type',kind,'status',run.status,'records_processed',run.records_processed,
  'recovered',recovered,'claimed_by',p_claimed_by,'claim',p_claim,'lease_expires_at',j.lease_expires_at,'payload',j.payload);
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_job_fail(p_tenant uuid, p_job uuid, p_attempt uuid, p_claimed_by text, p_claim integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;b public.learn_email_job_attempts%rowtype;r public.email_sync_runs%rowtype;receipt jsonb;code text;answer jsonb;begin
 if current_user<>'service_role' then raise exception 'learn_email_job_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_job is null or p_attempt is null or nullif(p_claimed_by,'') is null or p_claim is null or p_claim<1 then raise exception 'learn_email_job_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where tenant_id=p_tenant and id=p_job for update;
 if not found then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 receipt:=j.metadata->'learn_email_failure_v1';
 if j.status='dead_letter' and j.claimed_by=p_claimed_by and j.attempt_count=p_claim
  and receipt->>'attempt_id'=p_attempt::text and receipt->>'claimed_by'=p_claimed_by and receipt->>'claim'=p_claim::text
  and receipt->>'version'='learn-email-job-failure/1' then return receipt->'answer'||jsonb_build_object('disposition','replayed');end if;
 select * into b from public.learn_email_job_attempts where job_id=p_job and tenant_id=p_tenant and attempt_id=p_attempt;
 if not found then raise exception 'learn_email_job_binding_missing' using errcode='PT409';end if;
 perform public.learn_email_attempt_lease(p_attempt,p_claimed_by,p_claim);
 select * into r from public.email_sync_runs where id=b.attempt_id and tenant_id=b.tenant_id for key share;
 if not found or r.provider<>'gmail' or r.sync_type<>b.sync_type or r.status<>'failed' or r.completed_at is null
  or (r.metadata->>'email_account_id')::uuid is distinct from b.email_account_id then raise exception 'learn_email_attempt_not_failed' using errcode='PT409';end if;
 code:=case when r.error_message=any(array['history_expired','continuation_expired','pagination_no_progress','fetch_failed','parse_failed','persistence_failed','checkpoint_conflict','source_ineligible','unexpected_failure']) then r.error_message else 'capture_failed' end;
 answer:=jsonb_build_object('version','learn-email-job-failure/1','disposition','applied','job_id',j.id,'attempt_id',r.id,'code',code);
 receipt:=jsonb_build_object('version','learn-email-job-failure/1','attempt_id',r.id,'claimed_by',p_claimed_by,'claim',p_claim,'answer',answer);
 update public.platform_jobs set status='dead_letter',completed_at=clock_timestamp(),lease_expires_at=null,error_code=code,
  result=jsonb_build_object('sync_run_id',r.id,'error_code',code),metadata=coalesce(metadata,'{}')||jsonb_build_object('learn_email_failure_v1',receipt) where id=j.id;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'learn_email_job_not_owned' using errcode='PT409';end if;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_store_existing(p_context jsonb, p_ids jsonb, p_claimed_by text DEFAULT NULL::text, p_claim integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare result jsonb;begin
 perform public.learn_email_store_guard(p_context,p_claimed_by,p_claim);
 if jsonb_typeof(p_ids) is distinct from 'array' or jsonb_array_length(p_ids)>2000
  or exists(select 1 from jsonb_array_elements(p_ids)e where jsonb_typeof(e)<>'string' or (not (e#>>'{}')~'^[a-zA-Z0-9_-]+$' or length(e#>>'{}')>256))
 then raise exception 'learn_email_store_ids_invalid' using errcode='22023';end if;
 select coalesce(jsonb_agg(provider_message_id order by provider_message_id),'[]') into result from public.email_messages
  where tenant_id=(p_context->>'tenant_id')::uuid and provider='gmail' and provider_message_id in (select jsonb_array_elements_text(p_ids));
 perform public.learn_email_attempt_lease((p_context->>'attempt_id')::uuid,p_claimed_by,p_claim);
 return jsonb_build_object('version','learn-email-store/1','context',p_context,'existing_ids',result);
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_store_guard(p_context jsonb, p_claimed_by text, p_claim integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.email_accounts%rowtype;r public.email_sync_runs%rowtype;c public.email_ingestion_checkpoints%rowtype;
 v_tenant uuid;v_account uuid;v_attempt uuid;v_generation uuid;v_revision bigint;v_stream text;
begin
 if current_user<>'service_role' then raise exception 'learn_email_store_forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_context) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_context))<>8
  or not (p_context ?& array['tenant_id','email_account_id','attempt_id','stream','generation','revision','mailbox','fetch_policy'])
  or exists(select 1 from jsonb_each(p_context) e where jsonb_typeof(e.value)<>'string')
  or not coalesce(p_context->>'revision'~'^(0|[1-9][0-9]{0,18})$',false)
  or p_context->>'stream' not in ('recent','historical') or p_context->>'fetch_policy' not in ('missing_only','refetch_all')
  or nullif(btrim(p_context->>'mailbox'),'') is null
 then raise exception 'learn_email_store_context_invalid' using errcode='22023';end if;
 v_tenant:=(p_context->>'tenant_id')::uuid;v_account:=(p_context->>'email_account_id')::uuid;
 v_attempt:=(p_context->>'attempt_id')::uuid;v_generation:=(p_context->>'generation')::uuid;v_revision:=(p_context->>'revision')::bigint;v_stream:=p_context->>'stream';
 perform public.learn_email_attempt_lease(v_attempt,p_claimed_by,p_claim);
 perform pg_advisory_xact_lock(hashtextextended('learn-email-attempt:'||v_attempt::text,0));
 select * into a from public.email_accounts where id=v_account and tenant_id=v_tenant and provider='gmail' for update;
 if not found or lower(a.email_address) is distinct from lower(p_context->>'mailbox') then raise exception 'learn_email_store_account_mismatch' using errcode='PT409';end if;
 -- The account row serializes this read with all protocol transitions. The
 -- service role retains SELECT-only checkpoint access; no new progress privilege.
 select * into c from public.email_ingestion_checkpoints where tenant_id=v_tenant and email_account_id=v_account and email_ingestion_checkpoints.stream=v_stream;
 if not found or c.contract_version<>2 or c.state<>'claimed' or c.owner_attempt_id is distinct from v_attempt
  or c.generation is distinct from v_generation or c.revision is distinct from v_revision then raise exception 'learn_email_store_checkpoint_changed' using errcode='PT409';end if;
 select * into r from public.email_sync_runs where id=v_attempt and tenant_id=v_tenant for update;
 if not found or r.provider<>'gmail' or r.status<>'running' or (r.metadata->>'email_account_id')::uuid is distinct from v_account
  or (v_stream='historical' and r.sync_type<>'workspace_backfill') or (v_stream='recent' and r.sync_type not in ('messages','workspace_messages'))
 then raise exception 'learn_email_store_attempt_invalid' using errcode='PT409';end if;
 if not coalesce(case when r.sync_type='messages' then a.status='active' and a.auth_state in ('ok','unknown') else a.status in ('pending_tokenless_dwd','active_dwd') end,false)
 then raise exception 'learn_email_store_ineligible' using errcode='PT409';end if;
 if (v_stream='recent' and (c.continuation->>'phase' is distinct from 'initialized' or c.continuation->>'fetch_policy' is distinct from p_context->>'fetch_policy'))
  or (v_stream='historical' and p_context->>'fetch_policy'<>'missing_only') then raise exception 'learn_email_store_policy_changed' using errcode='PT409';end if;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_transition_apply(p_tenant uuid, p_account uuid, p_stream text, p_attempt uuid, p_request uuid, p_claimed_by text DEFAULT NULL::text, p_claim integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare r public.learn_email_transition_requests%rowtype; prior jsonb;answer jsonb;d jsonb;begin
 if current_user<>'service_role' then raise exception 'learn_email_outbox_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_account is null or p_attempt is null or p_request is null or p_stream is null or p_stream not in ('recent','historical') then raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 perform public.learn_email_attempt_lease(p_attempt,p_claimed_by,p_claim);
 perform pg_advisory_xact_lock(hashtextextended('learn-email-attempt:'||p_attempt::text,0));
 select * into r from public.learn_email_transition_requests where id=p_request and tenant_id=p_tenant and email_account_id=p_account and stream=p_stream and attempt_id=p_attempt;
 if not found then raise exception 'learn_email_outbox_request_missing' using errcode='42501';end if;
 select result into prior from public.learn_email_transition_settlements where request_id=r.id;
 -- A refused request has a final decision. It cannot apply later simply because
 -- account eligibility or checkpoint state changes; a new reviewed request is needed.
 if found and prior->>'disposition' in ('conflict','denied') then return prior;end if;
 d:=r.document;
 answer:=public.email_ingestion_transition_v2(r.tenant_id,r.email_account_id,r.stream,r.attempt_id,r.id,
  d->>'operation',(d->>'expectedGeneration')::uuid,(d->>'expectedRevision')::bigint,(d->>'expectedOwner')::uuid,d->'payload');
 if prior is null then
  insert into public.learn_email_transition_settlements(request_id,result) values(r.id,answer);
 end if;
 -- Replaying the protocol reads today's checkpoint alongside its historical
 -- receipt. Never return a cached successful response as current ownership.
 perform public.learn_email_attempt_lease(p_attempt,p_claimed_by,p_claim);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_transition_pending(p_tenant uuid, p_account uuid, p_stream text, p_attempt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare answer jsonb;begin
 if current_user<>'service_role' then raise exception 'learn_email_outbox_forbidden' using errcode='42501';end if;
 if p_tenant is null or p_account is null or p_attempt is null or p_stream is null or p_stream not in ('recent','historical') then raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-email-attempt:'||p_attempt::text,0));
 select r.document into answer from public.learn_email_transition_requests r
 where r.tenant_id=p_tenant and r.email_account_id=p_account and r.stream=p_stream and r.attempt_id=p_attempt
 and not exists(select 1 from public.learn_email_transition_settlements s where s.request_id=r.id) order by r.created_at,r.id limit 1;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_email_transition_prepare(p_document jsonb, p_claimed_by text DEFAULT NULL::text, p_claim integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare tenant uuid;account uuid;attempt uuid;request uuid;stream text;prior public.learn_email_transition_requests%rowtype;run public.email_sync_runs%rowtype; k text;
begin
 if current_user<>'service_role' then raise exception 'learn_email_outbox_forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_document) is distinct from 'object' or octet_length(p_document::text)>65536
  or not p_document ?& array['tenantId','accountId','attemptId','stream','transitionId','operation','expectedGeneration','expectedRevision','expectedOwner','payload']
  or (p_document-array['tenantId','accountId','attemptId','stream','transitionId','operation','expectedGeneration','expectedRevision','expectedOwner','payload'])<>'{}'::jsonb then
  raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 foreach k in array array['tenantId','accountId','attemptId','transitionId'] loop
  if jsonb_typeof(p_document->k) is distinct from 'string' or not coalesce(p_document->>k~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$',false) then
   raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 end loop;
 foreach k in array array['expectedGeneration','expectedOwner'] loop
  if p_document->k<>'null'::jsonb and (jsonb_typeof(p_document->k) is distinct from 'string' or not coalesce(p_document->>k~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$',false)) then
   raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 end loop;
 if p_document->'expectedRevision'<>'null'::jsonb then
  if jsonb_typeof(p_document->'expectedRevision') is distinct from 'string' or not coalesce(p_document->>'expectedRevision'~'^(0|[1-9][0-9]{0,18})$',false) then raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
  if (p_document->>'expectedRevision')::numeric>9223372036854775807 then raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 end if;
 if (p_document->'expectedGeneration'='null'::jsonb) is distinct from (p_document->'expectedRevision'='null'::jsonb)
  or (p_document->'expectedGeneration'='null'::jsonb and p_document->'expectedOwner'<>'null'::jsonb)
  or jsonb_typeof(p_document->'payload') is distinct from 'object'
  or not coalesce(p_document->>'stream'=any(array['recent','historical']),false)
  or not coalesce(p_document->>'operation'=any(array['claim','initialize_traversal','checkpoint','release','block','finish_attempt','takeover','restart']),false) then
   raise exception 'learn_email_outbox_invalid' using errcode='22023';end if;
 tenant:=(p_document->>'tenantId')::uuid;account:=(p_document->>'accountId')::uuid;
 attempt:=(p_document->>'attemptId')::uuid;request:=(p_document->>'transitionId')::uuid;stream:=p_document->>'stream';
 perform public.learn_email_attempt_lease(attempt,p_claimed_by,p_claim);
 perform pg_advisory_xact_lock(hashtextextended('learn-email-attempt:'||attempt::text,0));
 select * into prior from public.learn_email_transition_requests where id=request;
 if found then
  if prior.document<>p_document then raise exception 'learn_email_outbox_request_changed' using errcode='PT409';end if;
  return prior.document;
 end if;
 select * into run from public.email_sync_runs where tenant_id=tenant and id=attempt;
 if not found or run.provider<>'gmail' or run.status<>'running' or jsonb_typeof(run.metadata->'email_account_id') is distinct from 'string'
  or not coalesce(run.metadata->>'email_account_id'~*'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$',false) then
  raise exception 'learn_email_outbox_attempt_mismatch' using errcode='42501';end if;
 if (run.metadata->>'email_account_id')::uuid<>account
  or (stream='recent' and run.sync_type not in ('messages','workspace_messages')) or (stream='historical' and run.sync_type<>'workspace_backfill') then
  raise exception 'learn_email_outbox_attempt_mismatch' using errcode='42501';end if;
 if exists(select 1 from public.learn_email_transition_requests r where r.attempt_id=attempt and not exists(select 1 from public.learn_email_transition_settlements s where s.request_id=r.id)) then
  raise exception 'learn_email_outbox_pending_request' using errcode='PT409';end if;
 insert into public.learn_email_transition_requests(id,tenant_id,email_account_id,stream,attempt_id,document) values(request,tenant,account,stream,attempt,p_document);
 perform public.learn_email_attempt_lease(attempt,p_claimed_by,p_claim);
 return p_document;
end $function$

CREATE OR REPLACE FUNCTION public.learn_operator_capture_control_request(p_tenant uuid, p_request uuid, p_actor uuid, p_definition jsonb, p_mode text DEFAULT 'apply'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare prior public.learn_capture_control_requests%rowtype;previous jsonb;answer jsonb;k text;begin
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 if p_request is null or p_mode is null or p_mode not in ('apply','check','cancel') or jsonb_typeof(p_definition) is distinct from 'object'
  or octet_length(p_definition::text)>4000 then raise exception 'learn_capture_request_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-capture-request:'||p_request::text,0));
 select * into prior from public.learn_capture_control_requests where id=p_request;
 if found then
  if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.definition<>p_definition then
   raise exception 'learn_capture_request_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if p_mode='check' then return jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','pending');end if;
 if p_mode='cancel' then answer:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','cancelled');
 else
  if not p_definition ?& array['reason','revision','values'] or (p_definition-array['reason','revision','values'])<>'{}'::jsonb
   or jsonb_typeof(p_definition->'reason') is distinct from 'string' or length(btrim(p_definition->>'reason')) not between 1 and 1000
   or jsonb_typeof(p_definition->'revision') is distinct from 'string' or p_definition->>'revision'!~'^[a-f0-9]{32}$'
   or jsonb_typeof(p_definition->'values') is distinct from 'object' or (select count(*) from jsonb_object_keys(p_definition->'values'))<>4 then
   raise exception 'learn_capture_definition_invalid' using errcode='22023';end if;
  foreach k in array array['learn.enabled','learn.inputs.email.enabled','learn.inputs.phone.enabled','learn.inputs.slack.enabled'] loop
   if jsonb_typeof(p_definition->'values'->k) is distinct from 'boolean' then raise exception 'learn_capture_flags_invalid' using errcode='22023';end if;
  end loop;
  -- Same lock as existing Commusoft/master controls; concurrent operator edits cannot
  -- silently overwrite each other's master switch or admit a batch mid-update.
  perform pg_advisory_xact_lock(hashtextextended('learn-input-setup:'||p_tenant::text,0));
  previous:=public.learn_capture_control_state(p_tenant);
  if previous->>'revision' is distinct from p_definition->>'revision' then raise exception 'learn_capture_flags_changed' using errcode='PT409';end if;
  foreach k in array array['learn.enabled','learn.inputs.email.enabled','learn.inputs.phone.enabled','learn.inputs.slack.enabled'] loop
   update public.feature_flags set value=p_definition->'values'->k where tenant_id=p_tenant and flag=k;
   if not found then insert into public.feature_flags(tenant_id,flag,value) values(p_tenant,k,p_definition->'values'->k);end if;
  end loop;
  answer:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','recorded','controls',public.learn_capture_control_state(p_tenant));
 end if;
 insert into public.learn_capture_control_requests(id,tenant_id,actor_id,definition,receipt,previous_state)
  values(p_request,p_tenant,p_actor,p_definition,answer,previous);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_operator_input_access(p_tenant uuid, p_actor uuid, p_write boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare required_grant text:=case when p_write then 'platform.controlplane.admin' else 'platform.controlplane.view' end;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'learn_operator_snapshot_invalid' using errcode='22023';end if;
 if auth.role() is distinct from 'authenticated' or auth.uid() is null or p_actor is distinct from auth.uid()
  or p_tenant is null or p_write is null then raise exception 'learn_operator_forbidden' using errcode='42501';end if;
 perform 1 from public.profiles where id=auth.uid() for share;
 if not found then raise exception 'learn_operator_forbidden' using errcode='42501';end if;
 -- Retain the existing effective-dated authority model and fence revocation until
 -- this operation finishes. Platform access does not grant raw tenant data access.
 perform 1 from public.platform_authority_grants g where g.profile_id=auth.uid()
  and (g.permission=required_grant or
    (required_grant='platform.controlplane.view' and g.permission='platform.controlplane.admin'))
  and coalesce(effective_from,'-infinity')<=clock_timestamp()
  and coalesce(effective_to,'infinity')>clock_timestamp() for share;
 if not found or not public.current_user_is_openfolk_operator(required_grant) then
  raise exception 'learn_operator_forbidden' using errcode='42501';end if;
 if exists(select 1 from public.view_as_context where actor_user_id=auth.uid() and ended_at is null
  and (expires_at is null or expires_at>clock_timestamp())) then raise exception 'learn_operator_preview_forbidden' using errcode='42501';end if;
 perform 1 from public.tenants where id=p_tenant for share;
 if not found then raise exception 'learn_operator_tenant_unavailable' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_claim_jobs(p_worker uuid, p_batch integer DEFAULT 1)
 RETURNS SETOF platform_jobs
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;team text;pace public.slack_workspace_pacing%rowtype;
 claimed integer:=0;expires timestamptz;candidate uuid;begin
 if current_user<>'service_role' then raise exception 'slack_queue_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'slack_queue_snapshot' using errcode='22023';end if;
 if p_worker is null or p_batch is null or p_batch not between 1 and 5 then raise exception 'slack_queue_invalid' using errcode='22023';end if;
 -- Bounded scan; paced entries move out of the ready queue without consuming an
 -- attempt or becoming an error. Other workspaces can proceed in the same scan.
 for candidate in select q.id from public.platform_jobs q where q.job_type in ('slack.history_sync','slack.thread_sync')
  and q.status in ('queued','retrying','running') and coalesce(q.available_at,'-infinity')<=clock_timestamp()
  and public.learn_capture_job_allowed(q.tenant_id,q.job_type,q.metadata)
  and coalesce(q.lease_expires_at,'-infinity')<=clock_timestamp()
  order by q.priority,q.created_at,q.id limit 100
 loop
  exit when claimed>=p_batch;
  -- Lock only the row being considered: a prefetched FOR UPDATE cursor would
  -- otherwise lock other workspaces before this worker has chosen its one job.
  select * into j from public.platform_jobs q where q.id=candidate
   and q.job_type in ('slack.history_sync','slack.thread_sync') and q.status in ('queued','retrying','running')
   and coalesce(q.available_at,'-infinity')<=clock_timestamp() and coalesce(q.lease_expires_at,'-infinity')<=clock_timestamp()
   for update skip locked;
  if not found then continue;end if;
  if not public.learn_capture_job_allowed(j.tenant_id,j.job_type,j.metadata) then continue;end if;
  if j.attempt_count is null or j.max_attempts is null or j.max_attempts<1 or (j.attempt_count>=j.max_attempts and not(coalesce(j.metadata,'{}') ? 'slack_page_v1')) then
   update public.platform_jobs set status='dead_letter',dead_lettered_at=clock_timestamp(),failed_at=clock_timestamp(),
    lease_expires_at=null,error_code='slack_history_attempts_exhausted' where id=j.id;
   continue;
  end if;
  team:=null;
  -- A committed page needs only settlement. It never requests another provider
  -- page, so crash recovery is allowed even while that workspace is cooling down.
  if not(coalesce(j.metadata,'{}') ? 'slack_page_v1') then
   if j.job_type='slack.history_sync' then
    select a.settings->'slack_history'->>'teamId' into team from public.connector_accounts a
     join public.tenant_connectors c on c.id=a.tenant_connector_id and c.tenant_id=a.tenant_id and c.connector_id='slack'
     where a.id::text=j.payload->>'connector_account_id' and a.tenant_id=j.tenant_id;
   else
    select t.scope->>'teamId' into team from public.slack_thread_imports t
     join public.connector_accounts a on a.id=t.account_id and a.tenant_id=t.tenant_id
     join public.tenant_connectors c on c.id=a.tenant_connector_id and c.tenant_id=a.tenant_id and c.connector_id='slack'
     where t.id::text=j.payload->>'thread_import_id' and t.tenant_id=j.tenant_id and a.id::text=j.payload->>'connector_account_id';
   end if;
   if team is null or team !~ '^T[A-Z0-9]+$' then
    update public.platform_jobs set status='dead_letter',dead_lettered_at=clock_timestamp(),failed_at=clock_timestamp(),
     lease_expires_at=null,error_code='slack_history_binding_unavailable' where id=j.id;
    continue;
   end if;
   -- Never wait while holding other queue/gate rows. This also serializes the
   -- first insert when two workers see a previously unseen workspace.
   if not pg_try_advisory_xact_lock(hashtextextended('learn-slack-workspace:'||team,0)) then continue;end if;
   select * into pace from public.slack_workspace_pacing where team_id=team for update;
   if found and greatest(pace.next_allowed_at,pace.blocked_until)>clock_timestamp() then
    update public.platform_jobs set available_at=greatest(pace.blocked_until,least(pace.next_allowed_at,clock_timestamp()+interval '60 seconds')) where id=j.id;
    continue;
   end if;
  end if;
  expires:=clock_timestamp()+interval '180 seconds';
  if team is not null then
   insert into public.slack_workspace_pacing(team_id,next_allowed_at,active_job_id,last_started_at)
    values(team,expires+interval '60 seconds',j.id,clock_timestamp())
    on conflict(team_id) do update set next_allowed_at=excluded.next_allowed_at,active_job_id=excluded.active_job_id,last_started_at=excluded.last_started_at;
  end if;
  update public.platform_jobs set status='running',claimed_by='learn-slack:'||p_worker::text,
   claimed_at=clock_timestamp(),lease_expires_at=expires,attempt_count=j.attempt_count+1,last_attempt_at=clock_timestamp(),
   started_at=coalesce(started_at,clock_timestamp()),
   metadata=case when team is null then metadata else coalesce(metadata,'{}')||jsonb_build_object('slack_workspace_v1',jsonb_build_object('teamId',team)) end
   where id=j.id returning * into j;
  claimed:=claimed+1;
  return next j;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.phone_retry_state(p_stage text, p_runs jsonb, p_now timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  latest jsonb := p_runs->0;
  item jsonb;
  failures int := 0;
  delay_seconds int;
begin
  if latest is null then return 'ready'; end if;
  if latest->>'status' = 'running' then
    if (latest->>'started_at')::timestamptz > p_now - interval '5 minutes' then
      return 'in_progress';
    end if;
    return 'ready';
  end if;
  if latest->>'status' <> 'failed' or latest->>'failed_step' is distinct from p_stage then
    return 'ready';
  end if;
  if latest->>'error_code' = any(array[
    'invalid_audio','audio_too_short','audio_too_large','openai_invalid_request',
    'openai_quota_exhausted','openai_auth_failed','unsupported_format',
    'provider_recording_missing','invalid_recording','malformed_provider_id',
    'cross_tenant_mismatch','config_error','empty_audio'
  ]) then return 'needs_review'; end if;
  for item in select value from jsonb_array_elements(p_runs) loop
    exit when item->>'status' <> 'failed' or item->>'failed_step' is distinct from p_stage;
    failures := failures + 1;
    exit when failures >= 5;
  end loop;
  if failures >= 5 then return 'needs_review'; end if;
  delay_seconds := case failures when 1 then 60 when 2 then 300 when 3 then 900 else 3600 end;
  if (latest->>'started_at')::timestamptz > p_now - make_interval(secs => delay_seconds) then
    return 'cooldown';
  end if;
  return 'ready';
end;
$function$

CREATE OR REPLACE FUNCTION public.platform_jobs_complete_email_v1(p_job_id uuid, p_tenant_id uuid, p_claimed_by text, p_attempt_count integer, p_document jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 j public.platform_jobs%rowtype; run_row public.email_sync_runs%rowtype;
 successor public.platform_jobs%rowtype; receipt jsonb; result_doc jsonb;
 ingestion jsonb; continuation jsonb; expected_payload jsonb;
 account_id uuid; run_id uuid; successor_id uuid; expected_sync text;
 expected_stream text; expected_connector text; expected_priority integer;
 processed integer; affected integer;
BEGIN
 IF current_user <> 'service_role' THEN
  RAISE EXCEPTION USING errcode='42501',message='queue_completion_forbidden';
 END IF;
 IF p_job_id IS NULL OR p_tenant_id IS NULL OR p_claimed_by IS NULL OR
    p_claimed_by='' OR p_attempt_count IS NULL OR p_attempt_count<1 OR
    jsonb_typeof(p_document) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_invalid';
 END IF;
 IF NOT p_document ?& ARRAY['result','records_processed','continuation'] OR
    (SELECT count(*) FROM jsonb_object_keys(p_document))<>3 OR
    jsonb_typeof(p_document->'result') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_invalid';
 END IF;
 SELECT * INTO j FROM public.platform_jobs WHERE id=p_job_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001',message='queue_completion_not_owned'; END IF;
 receipt:=j.metadata->'email_queue_completion_v1';
 IF j.status='succeeded' THEN
  IF j.claimed_by=p_claimed_by AND j.attempt_count=p_attempt_count AND
     jsonb_typeof(receipt)='object' AND receipt->>'version'='1' AND
     receipt->>'claimed_by'=p_claimed_by AND
     receipt->>'attempt_count'=p_attempt_count::text AND
     receipt->'document'=p_document THEN
   RETURN jsonb_build_object('version',1,'disposition','replayed','job_id',j.id,
     'successor_id',receipt->'successor_id');
  END IF;
  RAISE EXCEPTION USING errcode='P0001',message='queue_completion_replay_conflict';
 END IF;
 IF j.status<>'running' OR j.claimed_by IS DISTINCT FROM p_claimed_by OR
    j.attempt_count<>p_attempt_count OR j.lease_expires_at IS NULL OR
    j.lease_expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='P0001',message='queue_completion_not_owned';
 END IF;
 IF j.job_type NOT IN ('email.gmail_sync','email.workspace_sync','email.workspace_backfill') OR
    jsonb_typeof(j.payload) IS DISTINCT FROM 'object' OR
    jsonb_typeof(j.payload->'email_account_id') IS DISTINCT FROM 'string' OR
    jsonb_typeof(j.metadata) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_invalid';
 END IF;
 account_id:=(j.payload->>'email_account_id')::uuid;
 IF j.job_key IS DISTINCT FROM j.job_type||':'||(j.payload->>'email_account_id') THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
 END IF;
 expected_sync:=CASE j.job_type WHEN 'email.gmail_sync' THEN 'messages'
  WHEN 'email.workspace_sync' THEN 'workspace_messages' ELSE 'workspace_backfill' END;
 expected_stream:=CASE WHEN j.job_type='email.workspace_backfill' THEN 'historical' ELSE 'recent' END;
 expected_connector:=CASE WHEN j.job_type='email.gmail_sync' THEN 'gmail' ELSE 'google-workspace' END;
 expected_priority:=CASE WHEN j.job_type='email.workspace_backfill' THEN 200 ELSE 100 END;
 result_doc:=p_document->'result'; ingestion:=result_doc->'ingestion';
 IF jsonb_typeof(ingestion) IS DISTINCT FROM 'object' OR ingestion->'success' IS DISTINCT FROM 'true'::jsonb OR
    ingestion->>'stream' IS DISTINCT FROM expected_stream OR
    (ingestion->>'email_account_id')::uuid IS DISTINCT FROM account_id OR
    jsonb_typeof(result_doc->'sync_run_id') IS DISTINCT FROM 'string' OR
    result_doc->>'sync_run_id' IS DISTINCT FROM ingestion->>'sync_run_id' THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
 END IF;
 run_id:=(result_doc->>'sync_run_id')::uuid;
 PERFORM 1 FROM public.email_accounts WHERE id=account_id AND tenant_id=j.tenant_id AND provider='gmail' FOR KEY SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity'; END IF;
 SELECT * INTO run_row FROM public.email_sync_runs WHERE id=run_id AND tenant_id=j.tenant_id
  AND provider='gmail' AND sync_type=expected_sync AND status='success' AND completed_at IS NOT NULL
  AND (metadata->>'email_account_id')::uuid=account_id FOR KEY SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity'; END IF;
 -- Worker counts are invocation-local; historical receipts retain the run's cumulative count.
 IF jsonb_typeof(p_document->'records_processed') IS DISTINCT FROM 'number' OR
    jsonb_typeof(ingestion->'records_processed') IS DISTINCT FROM 'number' OR
    jsonb_typeof(ingestion->'invocation_records_processed') IS DISTINCT FROM 'number' OR
    ingestion->'historical_receipt' NOT IN ('true'::jsonb,'false'::jsonb) OR
    ingestion->'historical_receipt' IS NULL THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_invalid';
 END IF;
 processed:=(p_document->>'records_processed')::integer;
 IF processed<0 OR (ingestion->>'records_processed')::integer<>run_row.records_processed OR
    processed<>(ingestion->>'invocation_records_processed')::integer THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
 END IF;
 IF ingestion->'historical_receipt'='true'::jsonb THEN
  IF processed<>0 OR ingestion->'threads_processed' IS DISTINCT FROM 'null'::jsonb OR
     ingestion->>'retry_action' IS DISTINCT FROM 'none' OR
     ingestion->>'persistence_certainty' IS DISTINCT FROM 'confirmed' OR
     ingestion->>'checkpoint_certainty' IS DISTINCT FROM 'confirmed' OR
     p_document->'continuation' IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
  END IF;
 ELSIF processed<>run_row.records_processed THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
 END IF;
 continuation:=p_document->'continuation';
 IF continuation<>'null'::jsonb THEN
  expected_payload:=jsonb_build_object('email_account_id',j.payload->'email_account_id')||
    CASE WHEN j.payload ? 'max_results' THEN jsonb_build_object('max_results',j.payload->'max_results') ELSE '{}'::jsonb END;
  IF jsonb_typeof(continuation) IS DISTINCT FROM 'object' OR
     ingestion->>'retry_action' IS DISTINCT FROM 'continue' OR
     ingestion->'historical_receipt' IS DISTINCT FROM 'false'::jsonb OR
     continuation IS DISTINCT FROM jsonb_build_object('job_type',j.job_type,'job_key',j.job_key,
       'connector_id',expected_connector,'module_id','communications.email',
       'priority',expected_priority,'payload',expected_payload) THEN
   RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
  END IF;
 ELSIF ingestion->>'retry_action'='continue' THEN
  RAISE EXCEPTION USING errcode='22023',message='queue_completion_identity';
 END IF;
 UPDATE public.platform_jobs SET status='succeeded',completed_at=clock_timestamp(),lease_expires_at=NULL,
  error_code=NULL,result=result_doc,records_processed=coalesce(processed,j.records_processed) WHERE id=j.id;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'queue_completion_disappeared'; END IF;
 IF continuation<>'null'::jsonb THEN
  INSERT INTO public.platform_jobs(tenant_id,connector_id,module_id,job_type,job_key,status,priority,
    max_attempts,available_at,payload)
  VALUES(j.tenant_id,expected_connector,'communications.email',j.job_type,j.job_key,'queued',expected_priority,
    5,clock_timestamp(),expected_payload)
  ON CONFLICT (tenant_id,job_key) WHERE job_key IS NOT NULL AND status IN ('queued','running','retrying')
  DO NOTHING RETURNING id INTO successor_id;
  IF successor_id IS NULL THEN
   SELECT * INTO successor FROM public.platform_jobs WHERE tenant_id=j.tenant_id AND job_key=j.job_key
    AND status IN ('queued','running','retrying') FOR UPDATE;
   IF NOT FOUND OR successor.job_type<>j.job_type OR successor.payload IS DISTINCT FROM expected_payload OR
      successor.connector_id IS DISTINCT FROM expected_connector OR
      successor.module_id IS DISTINCT FROM 'communications.email' OR successor.priority<>expected_priority THEN
    RAISE EXCEPTION USING errcode='P0001',message='queue_completion_successor_conflict';
   END IF;
   successor_id:=successor.id;
  END IF;
 END IF;
 IF j.lease_expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='P0001',message='queue_completion_not_owned';
 END IF;
 receipt:=jsonb_build_object('version',1,'claimed_by',p_claimed_by,'attempt_count',p_attempt_count,
  'document',p_document,'successor_id',successor_id);
 UPDATE public.platform_jobs SET metadata=metadata||jsonb_build_object('email_queue_completion_v1',receipt) WHERE id=j.id;
 RETURN jsonb_build_object('version',1,'disposition','applied','job_id',j.id,'successor_id',successor_id);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
 RAISE EXCEPTION USING errcode='22023',message='queue_completion_invalid';
END $function$

CREATE OR REPLACE FUNCTION public.client_programme_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id <> old.tenant_id then raise exception 'Programme tenant cannot change'; end if;
    new.version := old.version + 1;
  else
    new.version := 1;
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.operator_update_delivery(p_tenant uuid, p_version integer, p_content jsonb, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row public.client_delivery_updates; next_version integer; area jsonb;
begin
 if auth.uid() is null or not public.current_user_is_openfolk_operator('platform.controlplane.admin') then raise exception 'Operator administrator required' using errcode='42501'; end if;
 if exists(select 1 from public.view_as_context where actor_user_id=auth.uid() and ended_at is null and (expires_at is null or expires_at>now())) then raise exception 'Editing is unavailable in client preview' using errcode='42501'; end if;
 if p_version is null or p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>100000 or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then raise exception 'Valid delivery update and change reason required'; end if;
 if (p_content - array['summary','areas','readinessNote','next']) <> '{}'::jsonb then raise exception 'Unexpected delivery fields'; end if;
 if jsonb_typeof(p_content->'summary') is distinct from 'string' or length(btrim(p_content->>'summary')) not between 1 and 10000
 or jsonb_typeof(p_content->'next') is distinct from 'string' or length(btrim(p_content->>'next')) not between 1 and 10000
 or jsonb_typeof(p_content->'readinessNote') is distinct from 'string' or length(p_content->>'readinessNote')>10000
 or jsonb_typeof(p_content->'areas') is distinct from 'array' then raise exception 'Invalid delivery structure'; end if;
 if jsonb_array_length(p_content->'areas')>50 then raise exception 'Too many delivery areas'; end if;
 for area in select value from jsonb_array_elements(p_content->'areas') loop
   if jsonb_typeof(area)<>'object' or (area-array['title','status','detail'])<>'{}'::jsonb
   or jsonb_typeof(area->'title') is distinct from 'string' or length(btrim(area->>'title')) not between 1 and 200
   or jsonb_typeof(area->'status') is distinct from 'string' or length(btrim(area->>'status')) not between 1 and 100
   or jsonb_typeof(area->'detail') is distinct from 'string' or length(btrim(area->>'detail')) not between 1 and 10000 then raise exception 'Invalid delivery area'; end if;
 end loop;
 -- Parent lock serialises first publication as well as subsequent edits.
 perform 1 from public.client_programmes where tenant_id=p_tenant for update;
 if not found then raise exception 'Client programme not found'; end if;
 select * into old_row from public.client_delivery_updates where tenant_id=p_tenant for update;
 if coalesce(old_row.version,0)<>p_version then raise exception 'This delivery update changed. Reload before saving.' using errcode='40001'; end if;
 next_version:=coalesce(old_row.version,0)+1;
 insert into public.client_delivery_updates(tenant_id,content,verified_at,version) values(p_tenant,p_content,now(),next_version)
 on conflict(tenant_id) do update set content=excluded.content,verified_at=excluded.verified_at,version=excluded.version;
 insert into public.controlplane_change_log(tenant_id,actor,action,resource_type,resource_id,before,after,reason,source)
 values(p_tenant,auth.uid()::text,'client.delivery.updated','client_delivery',p_tenant::text,jsonb_build_object('content',old_row.content,'version',old_row.version),jsonb_build_object('content',p_content,'version',next_version),btrim(p_reason),'openfolk');
 return next_version;
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_queue_recurring_threads(p_account uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s public.slack_recurring_channels%rowtype;a public.connector_accounts%rowtype;i public.slack_history_imports%rowtype;
 w public.slack_recurring_thread_windows%rowtype;m record;request_id uuid;job_id uuid;key text;cfg jsonb;scope jsonb;scanned integer:=0;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 select * into s from public.slack_recurring_channels where account_id=p_account;
 if not found then return false;end if;
 -- Serialize direct calls with the channel scheduler and controls, in their lock order.
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-setup:'||s.tenant_id::text,0));
 select * into s from public.slack_recurring_channels where account_id=p_account for update;
 if not s.enabled or not s.include_threads or s.current_import is null then return false;end if;
 if not public.learn_capture_allowed(s.tenant_id,'slack') then return false;end if;
 perform 1 from public.profiles p where p.id=s.approved_by and
 ((p.tenant_id=s.tenant_id and p.role in ('owner','admin')) or exists(select 1 from public.platform_authority_grants g
 where g.profile_id=p.id and g.permission='platform.controlplane.admin'
 and coalesce(g.effective_from,'-infinity')<=now() and coalesce(g.effective_to,'infinity')>now())) for share;
 if not found then return false;end if;
 select * into a from public.connector_accounts where id=s.account_id and tenant_id=s.tenant_id for update;
 cfg:=a.settings->'slack_history';
 if not found or a.status<>'active' or cfg->'approved' is distinct from 'true'::jsonb
 or cfg->>'consentReference' is distinct from 'learn-slack-import:'||s.current_import::text
 or cfg->>'connectionId' is distinct from s.connection_id::text or cfg->>'teamId' is distinct from s.team_id
 or cfg->>'channelId' is distinct from s.channel_id or a.sync_cursor->'complete' is distinct from 'true'::jsonb then return false;end if;
 perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=s.tenant_id and connector_id='slack' and enabled and status='active' for share;
 if not found then return false;end if;
 perform 1 from public.provider_connections where id=s.connection_id and tenant_id=s.tenant_id and provider='slack'
 and status='configured' and revoked_at is null and updated_at=s.connection_revision and non_secret_config->>'team_id'=s.team_id
 and 'bot_token'=any(configured_fields) and secret_refs->>'bot_token' is not null for share;
 if not found then return false;end if;
 select * into i from public.slack_history_imports where id=s.current_import and tenant_id=s.tenant_id and account_id=s.account_id;
 if not found or i.definition->>'recurringAccountId' is distinct from s.account_id::text then return false;end if;
 if not exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_type='slack.history_sync' and status='succeeded'
 and payload->>'connector_account_id'=s.account_id::text and metadata->'slack_page_v1'->'next'=a.sync_cursor
 and metadata->'slack_page_v1'->>'account_id'=s.account_id::text) then return false;end if;
 insert into public.slack_recurring_thread_windows(history_import_id,tenant_id,account_id,recurring_revision)
 values(i.id,s.tenant_id,s.account_id,s.thread_revision) on conflict do nothing;
 select * into w from public.slack_recurring_thread_windows where history_import_id=i.id for update;
 if w.recurring_revision<>s.thread_revision then return false;end if;
 if not w.discovery_complete then
  for m in
   with observed as (
    select sm.*,case when sm.thread_timestamp is not null and sm.thread_timestamp::numeric<sm.provider_timestamp::numeric then sm.thread_timestamp
    when coalesce(sm.provider_payload->>'reply_count','') ~ '^[0-9]+$' and (sm.provider_payload->>'reply_count')::numeric>0 then sm.provider_timestamp end as parent
    from public.slack_messages sm where sm.tenant_id=s.tenant_id and sm.team_id=s.team_id and sm.channel_id=s.channel_id
   ), parents as (
    select distinct on (parent::numeric) id,source_version,parent from observed where parent is not null
    and parent::numeric<=(cfg->>'latest')::numeric and (w.after_parent is null or parent::numeric>w.after_parent)
    order by parent::numeric,id
   ) select * from parents order by parent::numeric limit 20
  loop
   request_id:=gen_random_uuid();job_id:=gen_random_uuid();
   key:='slack.thread:'||a.id::text||':'||m.parent||':'||extract(epoch from (i.definition->>'start')::timestamptz)::text||':'||extract(epoch from (i.definition->>'end')::timestamptz)::text;
   -- Recovery locks the window before the account. Do not wait while holding the account.
   if not pg_try_advisory_xact_lock(hashtextextended(key,0)) then return false;end if;
   if exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_key=key and status in ('queued','running','retrying')) then return false;end if;
   scope:=jsonb_build_object('approved',true,'connectionId',s.connection_id,'teamId',s.team_id,'channelId',s.channel_id,
    'parentTimestamp',m.parent,'oldest',cfg->>'oldest','latest',cfg->>'latest','consentReference','learn-slack-thread:'||request_id::text,
    'expiresAt',clock_timestamp()+interval '24 hours','maxPages',10);
   insert into public.platform_jobs(id,tenant_id,connector_id,job_type,job_key,status,max_attempts,available_at,payload,created_by)
   values(job_id,s.tenant_id,'slack','slack.thread_sync',key,'queued',5,clock_timestamp(),jsonb_build_object('thread_import_id',request_id,'connector_account_id',a.id),s.approved_by);
   insert into public.slack_thread_imports(id,tenant_id,account_id,source_message_id,initial_job_id,approved_by,definition,scope)
   values(request_id,s.tenant_id,a.id,m.id,job_id,s.approved_by,jsonb_build_object('accountId',a.id,'sourceMessageId',m.id,'sourceVersion',m.source_version,
    'connectionRevision',s.connection_revision,'start',i.definition->'start','end',i.definition->'end','maxPages',10,
    'recurringHistoryImportId',i.id,'recurringRevision',s.thread_revision,'reason','Approved recurring observed-thread capture'),scope);
   insert into public.slack_recurring_thread_members values(i.id,m.parent::numeric,request_id);
   update public.slack_recurring_thread_windows set after_parent=m.parent::numeric where history_import_id=i.id;
   scanned:=scanned+1;
  end loop;
  if scanned<20 then update public.slack_recurring_thread_windows set discovery_complete=true where history_import_id=i.id;else return false;end if;
 end if;
 return public.learn_slack_recurring_thread_window_complete(i.id);
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_read_thread_credential(p_tenant_id uuid, p_job_id uuid, p_claimed_by text, p_attempt_count integer, p_connection_id uuid, p_revision timestamp with time zone, p_secret_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;t public.slack_thread_imports%rowtype;a public.connector_accounts%rowtype;cfg jsonb;secret text;begin
 if auth.role() is distinct from 'service_role' then raise exception 'slack_credential_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'slack_credential_snapshot' using errcode='22023';end if;
 select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
 if not found or j.status<>'running' or j.job_type<>'slack.thread_sync' or
  p_claimed_by is null or j.claimed_by is distinct from p_claimed_by or p_attempt_count is null or j.attempt_count is distinct from p_attempt_count
  or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp() or j.metadata ? 'slack_page_v1' then return null;end if;
 select * into t from public.slack_thread_imports where id=(j.payload->>'thread_import_id')::uuid and tenant_id=p_tenant_id for share;
 if not found or j.payload->>'connector_account_id' is distinct from t.account_id::text then return null;end if;
 select * into a from public.connector_accounts where id=t.account_id and tenant_id=p_tenant_id for share;
 if not found or a.status<>'active' then return null;end if;
 if not public.learn_slack_recurring_thread_allowed(p_tenant_id,t.id) then raise exception 'slack_recurring_thread_paused' using errcode='42501';end if;
 cfg:=t.scope;
 if cfg->'approved' is distinct from 'true'::jsonb or coalesce((cfg->>'expiresAt')::timestamptz,'-infinity')<=clock_timestamp()
  or (cfg->>'connectionId')::uuid is distinct from p_connection_id then return null;end if;
 perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id and connector_id='slack' and enabled and status='active' for share;
 if not found then return null;end if;
 perform 1 from public.provider_connections where id=p_connection_id and tenant_id=p_tenant_id and provider='slack'
  and status='configured' and revoked_at is null and updated_at=p_revision and non_secret_config->>'team_id'=cfg->>'teamId'
  and 'bot_token'=any(configured_fields) and secret_refs->>'bot_token'=p_secret_id::text for share;
 if not found then return null;end if;
 select decrypted_secret into secret from vault.decrypted_secrets where id=p_secret_id and name='provider_secret:'||p_tenant_id::text||':slack:bot_token';
 if j.lease_expires_at<=clock_timestamp() then return null;end if;
 return secret;
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_recurring_control(p_tenant uuid, p_request uuid, p_account uuid, p_revision bigint, p_enabled boolean, p_reason text, p_mode text DEFAULT 'apply'::text, p_actor uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.connector_accounts%rowtype;c public.provider_connections%rowtype;
 s public.slack_recurring_channels%rowtype;r public.slack_recurring_requests%rowtype;
 definition jsonb;answer jsonb;cfg jsonb;boundary timestamptz;resume_paused boolean;
begin
 if current_setting('transaction_isolation')<>'read committed' then
  raise exception 'slack_recurring_snapshot' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-work-registry',0));
 perform pg_advisory_xact_lock(hashtextextended('learn-roster:'||p_tenant::text,0));
 if p_actor is distinct from auth.uid() or not public.learn_slack_recurring_access(p_tenant,true) then
  raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 if p_request is null or p_account is null or p_revision is null or p_revision<0 or p_enabled is null
  or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or p_mode is null or p_mode not in ('apply','check','cancel') then
  raise exception 'slack_recurring_invalid' using errcode='22023';end if;
 definition:=jsonb_build_object('accountId',p_account,'revision',p_revision,'enabled',p_enabled,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-recurring-request:'||p_request::text,0));
 select * into r from public.slack_recurring_requests where id=p_request;
 if found then
  if r.tenant_id<>p_tenant or r.actor_id<>auth.uid() or r.definition<>definition then
   raise exception 'slack_recurring_request_changed' using errcode='40001';end if;
  return r.receipt;
 end if;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,
  'state',case when p_mode='cancel' then 'cancelled' else 'pending' end);
 if p_mode='check' then return answer;end if;
 if p_mode='cancel' then
  insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
  return answer;
 end if;
 -- Same setup lock as manual channel imports; subscription precedes account locks.
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-setup:'||p_tenant::text,0));
 select * into s from public.slack_recurring_channels where account_id=p_account for update;
 if (found and (s.tenant_id<>p_tenant or s.revision<>p_revision)) or (not found and p_revision<>0) then
  raise exception 'slack_recurring_changed' using errcode='40001';end if;
 select * into a from public.connector_accounts where id=p_account and tenant_id=p_tenant for update;
 if not found then raise exception 'slack_recurring_account_unavailable' using errcode='42501';end if;
 cfg:=a.settings->'slack_history';
 resume_paused:=s.account_id is not null and not s.enabled and s.current_import is not null
  and cfg->>'consentReference'='learn-slack-import:'||s.current_import::text
  and cfg->'approved'='false'::jsonb;
 resume_paused:=coalesce(resume_paused,false);
 if p_enabled and s.include_threads and s.current_import is not null and not resume_paused and not public.learn_slack_recurring_thread_window_complete(s.current_import) then raise exception 'slack_recurring_threads_incomplete' using errcode='55000';end if;
 if p_enabled then
  if a.status is distinct from 'active' or coalesce(cfg->>'channelId','') !~ '^C[A-Z0-9]+$'
   or coalesce(cfg->>'teamId','') !~ '^T[A-Z0-9]+$'
   or coalesce(cfg->>'latest','') !~ '^\d{1,12}\.\d{1,6}$'
   or not exists(select 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant
    and connector_id='slack' and enabled and status='active') then
   raise exception 'slack_recurring_finish_initial_import' using errcode='55000';end if;
  if not resume_paused and a.sync_cursor->'complete' is distinct from 'true'::jsonb then
   raise exception 'slack_recurring_finish_initial_import' using errcode='55000';end if;
  if not resume_paused and exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='slack.history_sync'
   and payload->>'connector_account_id'=p_account::text and status in ('queued','running','retrying')) then
   raise exception 'slack_recurring_window_active' using errcode='55000';end if;
  -- A true checkpoint alone is insufficient: require matching durable publication.
  if not resume_paused and not exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='slack.history_sync'
   and payload->>'connector_account_id'=p_account::text and status='succeeded'
   and metadata->'slack_page_v1'->'next'=a.sync_cursor
   and metadata->'slack_page_v1'->>'account_id'=p_account::text) then
   raise exception 'slack_recurring_completion_unverified' using errcode='55000';end if;
  select * into c from public.provider_connections where id=(cfg->>'connectionId')::uuid and tenant_id=p_tenant for share;
  if not found or c.provider is distinct from 'slack' or c.status is distinct from 'configured' or c.revoked_at is not null
   or c.non_secret_config->>'team_id' is distinct from cfg->>'teamId'
   or ('bot_token'=any(c.configured_fields)) is distinct from true or c.secret_refs->>'bot_token' is null then
   raise exception 'slack_recurring_connection_unavailable' using errcode='55000';end if;
  boundary:=to_timestamp((cfg->>'latest')::double precision);
  if boundary>clock_timestamp() then raise exception 'slack_recurring_future_window' using errcode='22023';end if;
  if resume_paused then
   if c.id<>s.connection_id or c.updated_at<>s.connection_revision or cfg->>'teamId'<>s.team_id or cfg->>'channelId'<>s.channel_id then
    raise exception 'slack_recurring_connection_changed' using errcode='40001';end if;
   -- Restore only the approved unfinished scope. Expiry and page limits stay as
   -- recorded; exhausted work still uses the explicit existing recovery flow.
   update public.slack_recurring_channels set enabled=true,revision=revision+1,approved_by=auth.uid(),
    last_state='ready',next_check_at=clock_timestamp(),updated_at=clock_timestamp()
    where account_id=p_account returning * into s;
  else
  insert into public.slack_recurring_channels(account_id,tenant_id,connection_id,connection_revision,team_id,channel_id,approved_by,enabled,next_start)
   values(p_account,p_tenant,c.id,c.updated_at,cfg->>'teamId',cfg->>'channelId',auth.uid(),true,boundary)
   on conflict(account_id) do update set connection_id=excluded.connection_id,connection_revision=excluded.connection_revision,
    team_id=excluded.team_id,channel_id=excluded.channel_id,
    approved_by=excluded.approved_by,enabled=true,next_start=excluded.next_start,current_import=null,
    revision=slack_recurring_channels.revision+1,last_state='ready',next_check_at=clock_timestamp(),updated_at=clock_timestamp()
   returning * into s;
  end if;
  update public.connector_accounts set settings=jsonb_set(settings,'{slack_history,approved}','true') where id=p_account;
 else
  if s.account_id is null then raise exception 'slack_recurring_not_configured' using errcode='55000';end if;
  update public.slack_recurring_channels set enabled=false,revision=revision+1,last_state='disabled',updated_at=clock_timestamp()
   where account_id=p_account returning * into s;
  -- Stop further requests for this recurring window without erasing its checkpoint.
  if s.current_import is not null and cfg->>'consentReference'='learn-slack-import:'||s.current_import::text then
   update public.connector_accounts set settings=jsonb_set(settings,'{slack_history,approved}','false') where id=p_account;
  end if;
 end if;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,'state','recorded','enabled',s.enabled,'revision',s.revision);
 insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_recurring_threads_control(p_tenant uuid, p_request uuid, p_account uuid, p_revision bigint, p_enabled boolean, p_reason text, p_mode text DEFAULT 'apply'::text, p_actor uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s public.slack_recurring_channels%rowtype;r public.slack_recurring_requests%rowtype;definition jsonb;answer jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'slack_recurring_snapshot' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-work-registry',0));
 perform pg_advisory_xact_lock(hashtextextended('learn-roster:'||p_tenant::text,0));
 if p_actor is distinct from auth.uid() or not public.learn_slack_recurring_access(p_tenant,true) then raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 if p_request is null or p_account is null or p_revision is null or p_revision<1 or p_enabled is null
 or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or p_mode is null or p_mode not in ('apply','check','cancel') then raise exception 'slack_recurring_invalid' using errcode='22023';end if;
 definition:=jsonb_build_object('kind','observed_threads','accountId',p_account,'revision',p_revision,'enabled',p_enabled,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-recurring-request:'||p_request::text,0));
 select * into r from public.slack_recurring_requests where id=p_request;
 if found then
  if r.tenant_id<>p_tenant or r.actor_id<>auth.uid() or r.definition<>definition then raise exception 'slack_recurring_request_changed' using errcode='40001';end if;
  return r.receipt;
 end if;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,'state',case when p_mode='cancel' then 'cancelled' else 'pending' end);
 if p_mode='check' then return answer;end if;
 if p_mode='cancel' then
  insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
  return answer;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-setup:'||p_tenant::text,0));
 select * into s from public.slack_recurring_channels where account_id=p_account and tenant_id=p_tenant for update;
 if not found or s.revision<>p_revision then raise exception 'slack_recurring_changed' using errcode='40001';end if;
 if p_enabled and not s.enabled then raise exception 'slack_recurring_channel_disabled' using errcode='55000';end if;
 -- Do not attach a new approval to an already-discovered window. Disabling is always allowed;
 -- re-enabling waits for a fresh channel window, retaining all earlier thread evidence.
 if p_enabled and exists(select 1 from public.slack_recurring_thread_windows where history_import_id=s.current_import) then
  raise exception 'slack_recurring_thread_window_started' using errcode='55000';end if;
 update public.slack_recurring_channels set include_threads=p_enabled,thread_revision=thread_revision+1,revision=revision+1,approved_by=auth.uid(),
  next_check_at=clock_timestamp(),updated_at=clock_timestamp() where account_id=p_account returning * into s;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,'state','recorded','enabled',s.include_threads,'revision',s.revision);
 insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_resume_thread(p_tenant_id uuid, p_request_id uuid, p_import_id uuid, p_expected_state_version text, p_mode text, p_max_pages integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare t public.slack_thread_imports%rowtype;prior public.slack_thread_imports%rowtype;a public.connector_accounts%rowtype;c public.provider_connections%rowtype;
 state jsonb;cfg jsonb;cp jsonb;definition jsonb;scope jsonb;checkpoint jsonb;key text;job_id uuid:=gen_random_uuid();
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'Thread recovery requires a fresh snapshot' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-work-registry',0));
 perform pg_advisory_xact_lock(hashtextextended('learn-roster:'||p_tenant_id::text,0));
 if auth.uid() is null or p_tenant_id is distinct from public.current_tenant_id() or coalesce(public.current_user_role(),'') not in ('owner','admin')
  or exists(select 1 from public.view_as_context where actor_user_id=auth.uid() and ended_at is null and (expires_at is null or expires_at>clock_timestamp())) then
  raise exception 'Company owner/admin access required outside preview' using errcode='42501';end if;
 if p_request_id is null or p_import_id is null or coalesce(p_expected_state_version,'') !~ '^[a-f0-9]{64}$'
  or p_mode is null or p_mode not in ('continue','restart') or p_max_pages is null or p_max_pages not between 1 and 10
  or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 then raise exception 'Invalid thread recovery approval' using errcode='22023';end if;
 definition:=jsonb_build_object('recovery',jsonb_build_object('importId',p_import_id,'stateVersion',p_expected_state_version,'mode',p_mode,'maxPages',p_max_pages,'reason',btrim(p_reason)));
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-thread-request:'||p_request_id::text,0));
 select * into prior from public.slack_thread_imports where id=p_request_id;
 if found then
  if prior.tenant_id<>p_tenant_id or prior.approved_by<>auth.uid() or prior.definition->'recovery' is distinct from definition->'recovery' then raise exception 'Thread recovery request identity changed' using errcode='PT409';end if;
  return jsonb_build_object('requestId',prior.id,'previousImportId',p_import_id,'accountId',prior.account_id,'jobId',prior.initial_job_id,'reused',true);
 end if;
 select * into t from public.slack_thread_imports where id=p_import_id and tenant_id=p_tenant_id;
 if not found then raise exception 'Stored thread import unavailable' using errcode='42501';end if;
 state:=public.learn_slack_thread_recovery_state(p_tenant_id,p_import_id);key:=state->>'jobKey';
 if state->'stateValid' is distinct from 'true'::jsonb or key is null then raise exception 'Thread recovery unavailable' using errcode='55000';end if;
 -- Share initial approval's exact window lock. Existing workers lock their import
 -- before publishing or completing; a still-active job always refuses recovery.
 perform pg_advisory_xact_lock(hashtextextended(key,0));
 select * into c from public.provider_connections where id::text=t.scope->>'connectionId' and tenant_id=p_tenant_id and provider='slack' for share;
 if not found then raise exception 'Thread connection unavailable' using errcode='55000';end if;
 select * into a from public.connector_accounts where id=t.account_id and tenant_id=p_tenant_id for share;
 perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id and connector_id='slack' for share;
 select * into t from public.slack_thread_imports where id=p_import_id and tenant_id=p_tenant_id for update;
 state:=public.learn_slack_thread_recovery_state(p_tenant_id,p_import_id);
 if state->>'stateVersion' is distinct from p_expected_state_version then raise exception 'Thread progress changed; reload review' using errcode='PT409';end if;
 if state->'stateValid' is distinct from 'true'::jsonb or state->'connectionReady' is distinct from 'true'::jsonb
  or state->'active'='true'::jsonb or state->>'supersededBy' is not null then raise exception 'Thread recovery unavailable' using errcode='55000';end if;
 cfg:=state->'scope';cp:=state->'checkpoint';
 if cp->'complete'='true'::jsonb then raise exception 'This thread window is already captured' using errcode='55000';end if;
 if p_mode='continue' and cp<>'{}'::jsonb and cp->>'cursor' is null and cp->'pages'<>'0'::jsonb then raise exception 'No saved cursor; review a thread restart' using errcode='55000';end if;
 scope:=cfg||jsonb_build_object('approved',true,'maxPages',p_max_pages,'expiresAt',clock_timestamp()+interval '24 hours','consentReference','learn-slack-thread:'||p_request_id::text);
 checkpoint:=jsonb_build_object('scopeKey',array_to_json(array[p_tenant_id::text,scope->>'teamId',scope->>'channelId',scope->>'oldest',scope->>'latest',scope->>'consentReference',scope->>'parentTimestamp'])::text,
  'cursor',case when p_mode='continue' then cp->>'cursor' else null end,'pages',0,'complete',false);
 definition:=(t.definition-array['recovery','previousState','resumesImportId'])||definition||jsonb_build_object('connectionRevision',c.updated_at,'maxPages',p_max_pages,'reason',btrim(p_reason),
  'resumesImportId',t.id,'previousState',jsonb_build_object('scope',cfg,'checkpoint',cp));
 insert into public.platform_jobs(id,tenant_id,connector_id,job_type,job_key,status,max_attempts,available_at,payload,created_by)
  values(job_id,p_tenant_id,'slack','slack.thread_sync',key,'queued',5,clock_timestamp(),jsonb_build_object('thread_import_id',p_request_id,'connector_account_id',t.account_id),auth.uid());
 insert into public.slack_thread_imports(id,tenant_id,account_id,source_message_id,initial_job_id,approved_by,definition,scope,checkpoint)
  values(p_request_id,p_tenant_id,t.account_id,t.source_message_id,job_id,auth.uid(),definition,scope,checkpoint);
 return jsonb_build_object('requestId',p_request_id,'previousImportId',t.id,'accountId',t.account_id,'jobId',job_id,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_schedule_recurring(p_batch integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s public.slack_recurring_channels%rowtype;a public.connector_accounts%rowtype;
 c public.provider_connections%rowtype;cfg jsonb;previous jsonb;approval jsonb;
 boundary timestamptz;ending timestamptz;request_id uuid;job_id uuid;state text;
 checked integer:=0;queued integer:=0;held integer:=0;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' or p_batch is null or p_batch not between 1 and 50 then
  raise exception 'slack_recurring_invalid' using errcode='22023';end if;
 -- Select due IDs before taking the established tenant setup lock. All callers
 -- then take the subscription and account locks in that same order.
 for s in select * from public.slack_recurring_channels where enabled and next_check_at<=clock_timestamp()
  order by next_check_at,account_id limit p_batch
 loop
  if not pg_try_advisory_xact_lock(hashtextextended('learn-slack-setup:'||s.tenant_id::text,0)) then continue;end if;
  select * into s from public.slack_recurring_channels where account_id=s.account_id and enabled
   and next_check_at<=clock_timestamp() for update;
  if not found then continue;end if;
  checked:=checked+1;state:='ready';boundary:=s.next_start;
  if not public.learn_capture_allowed(s.tenant_id,'slack') then state:='capture_paused';
  end if;
  perform 1 from public.profiles p where p.id=s.approved_by and
   ((p.tenant_id=s.tenant_id and p.role in ('owner','admin')) or exists(select 1 from public.platform_authority_grants g
     where g.profile_id=p.id and g.permission='platform.controlplane.admin'
     and coalesce(g.effective_from,'-infinity')<=now() and coalesce(g.effective_to,'infinity')>now())) for share;
  if state='ready' and not found then state:='approval_changed';end if;
  select * into a from public.connector_accounts where id=s.account_id and tenant_id=s.tenant_id for update;
  if not found or a.status is distinct from 'active' then state:='account_unavailable';end if;
  cfg:=a.settings->'slack_history';
  if state='ready' and cfg->'approved' is distinct from 'true'::jsonb then state:='approval_changed';end if;
  select * into c from public.provider_connections where id=s.connection_id and tenant_id=s.tenant_id for share;
  if not found or c.provider is distinct from 'slack' or c.status is distinct from 'configured' or c.revoked_at is not null
   or c.updated_at is distinct from s.connection_revision or c.non_secret_config->>'team_id' is distinct from cfg->>'teamId'
   or cfg->>'connectionId' is distinct from s.connection_id::text or ('bot_token'=any(c.configured_fields)) is distinct from true
   or cfg->>'teamId' is distinct from s.team_id or cfg->>'channelId' is distinct from s.channel_id
   or c.secret_refs->>'bot_token' is null then state:='connection_changed';end if;
  if not exists(select 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=s.tenant_id
   and connector_id='slack' and enabled and status='active') then state:='connector_paused';end if;
  if state='ready' and exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_type='slack.history_sync'
   and payload->>'connector_account_id'=s.account_id::text and status in ('queued','running','retrying')) then state:='window_active';end if;
  if state='ready' then
   if s.current_import is not null and cfg->>'consentReference' is distinct from 'learn-slack-import:'||s.current_import::text then state:='window_changed';
   elsif a.sync_cursor->'complete' is distinct from 'true'::jsonb then state:='window_incomplete';
   elsif not exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_type='slack.history_sync'
    and payload->>'connector_account_id'=s.account_id::text and status='succeeded'
    and metadata->'slack_page_v1'->'next'=a.sync_cursor and metadata->'slack_page_v1'->>'account_id'=s.account_id::text)
    then state:='completion_unverified';
   elsif coalesce(cfg->>'latest','') !~ '^\d{1,12}\.\d{1,6}$' then state:='window_changed';
   else
    boundary:=to_timestamp((cfg->>'latest')::double precision);
    if (s.current_import is null and boundary is distinct from s.next_start) or boundary<s.next_start then state:='window_changed';end if;
   end if;
  end if;
  if state='ready' and s.include_threads and s.current_import is not null then
   if not public.learn_slack_queue_recurring_threads(s.account_id) then state:='threads_pending';end if;
  end if;
  if state='ready' then
   -- Fifteen-minute windows bound busy-channel pages; 2-minute settling delay.
   ending:=least(boundary+interval '15 minutes',clock_timestamp()-interval '2 minutes');
   if ending-boundary<interval '1 minute' then state:='caught_up';
   else
    request_id:=gen_random_uuid();job_id:=gen_random_uuid();
    previous:=jsonb_build_object('settings',cfg,'checkpoint',a.sync_cursor);
    approval:=jsonb_build_object('approved',true,'connectionId',c.id,'teamId',cfg->>'teamId','channelId',cfg->>'channelId',
     'oldest',to_char(extract(epoch from boundary),'FM999999999999.000000'),
     'latest',to_char(extract(epoch from ending),'FM999999999999.000000'),
     'consentReference','learn-slack-import:'||request_id::text,'expiresAt',clock_timestamp()+interval '24 hours','maxPages',10);
    update public.connector_accounts set settings=settings||jsonb_build_object('slack_history',approval),sync_cursor='{}' where id=a.id;
    insert into public.platform_jobs(id,tenant_id,connector_id,job_type,job_key,status,max_attempts,available_at,payload,created_by)
     values(job_id,s.tenant_id,'slack','slack.history_sync','slack.history:'||a.id::text,'queued',5,clock_timestamp(),jsonb_build_object('connector_account_id',a.id),s.approved_by);
    insert into public.slack_history_imports(id,tenant_id,account_id,job_id,approved_by,definition,previous_state)
     values(request_id,s.tenant_id,a.id,job_id,s.approved_by,jsonb_build_object('connectionId',c.id,'connectionRevision',c.updated_at,
      'channelId',cfg->>'channelId','start',boundary,'end',ending,'maxPages',10,'recurringAccountId',a.id,
      'recurringRevision',s.revision,'reason','Approved recurring channel capture'),previous);
    update public.slack_recurring_channels set current_import=request_id,next_start=boundary where account_id=a.id;
    queued:=queued+1;state:='window_queued';
   end if;
  end if;
  if state not in ('window_queued','window_active','caught_up') then held:=held+1;end if;
  update public.slack_recurring_channels set last_state=state,next_check_at=clock_timestamp()+interval '60 seconds',updated_at=clock_timestamp() where account_id=s.account_id;
 end loop;
 return jsonb_build_object('checked',checked,'queued',queued,'held',held);
end $function$

CREATE OR REPLACE FUNCTION public.learn_slack_thread_recovery_state(p_tenant_id uuid, p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare t public.slack_thread_imports%rowtype;a public.connector_accounts%rowtype;c public.provider_connections%rowtype;
 tc public.tenant_connectors%rowtype;j public.platform_jobs%rowtype;cfg jsonb;cp jsonb;valid boolean:=false;ready boolean:=false;
 active boolean;newer uuid;key text;fingerprint text;
begin
 select * into t from public.slack_thread_imports where id=p_import_id and tenant_id=p_tenant_id;
 if not found then return null;end if;
 select * into a from public.connector_accounts where id=t.account_id and tenant_id=p_tenant_id;
 if not found then return null;end if;
 select * into tc from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id and connector_id='slack';
 if not found then return null;end if;
 cfg:=t.scope;cp:=t.checkpoint;
 select * into c from public.provider_connections where id::text=cfg->>'connectionId' and tenant_id=p_tenant_id and provider='slack';
 ready:=found and a.status='active' and tc.enabled and tc.status='active' and c.status='configured' and c.revoked_at is null
  and c.non_secret_config->>'team_id'=cfg->>'teamId' and 'bot_token'=any(c.configured_fields) and c.secret_refs->>'bot_token' is not null
  and a.settings->'slack_history'->>'connectionId'=cfg->>'connectionId'
  and a.settings->'slack_history'->>'teamId'=cfg->>'teamId' and a.settings->'slack_history'->>'channelId'=cfg->>'channelId';
 begin
  valid:=cfg->'approved'='true'::jsonb and cfg->>'consentReference'='learn-slack-thread:'||t.id::text
   and cfg->>'teamId' ~ '^T[A-Z0-9]+$' and cfg->>'channelId' ~ '^C[A-Z0-9]+$'
   and cfg->>'parentTimestamp' ~ '^\d{1,12}\.\d{1,6}$' and cfg->>'oldest' ~ '^\d{1,12}\.\d{1,6}$' and cfg->>'latest' ~ '^\d{1,12}\.\d{1,6}$'
   and (cfg->>'latest')::numeric>(cfg->>'oldest')::numeric and (cfg->>'latest')::numeric-(cfg->>'oldest')::numeric<=86400
   and (cfg->>'parentTimestamp')::numeric<=(cfg->>'latest')::numeric
   and (cfg->>'oldest')::numeric=extract(epoch from (t.definition->>'start')::timestamptz)
   and (cfg->>'latest')::numeric=extract(epoch from (t.definition->>'end')::timestamptz)
   and isfinite((cfg->>'expiresAt')::timestamptz)
   and jsonb_typeof(cfg->'maxPages')='number' and cfg->>'maxPages' ~ '^[0-9]+$' and (cfg->>'maxPages')::integer between 1 and 10 and cfg->'maxPages'=t.definition->'maxPages'
   and (cp='{}'::jsonb or (jsonb_typeof(cp)='object' and (select count(*)=4 from jsonb_object_keys(cp))
    and (cp->>'scopeKey')::jsonb=jsonb_build_array(p_tenant_id::text,cfg->>'teamId',cfg->>'channelId',cfg->>'oldest',cfg->>'latest',cfg->>'consentReference',cfg->>'parentTimestamp')
    and jsonb_typeof(cp->'pages')='number' and cp->>'pages' ~ '^\d+$' and (cp->>'pages')::integer between 0 and (cfg->>'maxPages')::integer
    and jsonb_typeof(cp->'complete')='boolean' and (cp->'cursor'='null'::jsonb or jsonb_typeof(cp->'cursor')='string' and length(cp->>'cursor') between 1 and 1024)
    and (cp->'complete'<>'true'::jsonb or cp->'cursor'='null'::jsonb)));
  key:='slack.thread:'||t.account_id::text||':'||(cfg->>'parentTimestamp')||':'||extract(epoch from (t.definition->>'start')::timestamptz)::text||':'||extract(epoch from (t.definition->>'end')::timestamptz)::text;
 exception when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format or datetime_field_overflow then valid:=false;
 end;
 select id into newer from public.slack_thread_imports where tenant_id=p_tenant_id and account_id=t.account_id
  and ((approved_at,id)>(t.approved_at,t.id) or definition->>'resumesImportId'=t.id::text) and scope->>'parentTimestamp'=cfg->>'parentTimestamp'
  and scope->>'oldest'=cfg->>'oldest' and scope->>'latest'=cfg->>'latest' order by approved_at desc,id desc limit 1;
 select * into j from public.platform_jobs where tenant_id=p_tenant_id and job_type='slack.thread_sync'
  and payload->>'thread_import_id'=t.id::text order by created_at desc,id desc limit 1;
 select exists(select 1 from public.platform_jobs where tenant_id=p_tenant_id and job_type='slack.thread_sync'
  and (job_key=key or payload->>'thread_import_id'=t.id::text) and status in ('queued','running','retrying')) into active;
 fingerprint:=encode(sha256(convert_to(jsonb_build_array(t.id,t.definition,cfg,cp,a.id,a.status,a.settings->'slack_history'->>'connectionId',
  a.settings->'slack_history'->>'teamId',a.settings->'slack_history'->>'channelId',tc.enabled,tc.status,c.id,c.updated_at,c.status,c.revoked_at,
  c.non_secret_config->>'team_id',ready,active,newer,j.id,j.status,j.attempt_count,j.available_at,j.error_code,j.result->>'stopReason')::text,'UTF8')),'hex');
 return jsonb_build_object('tenantId',p_tenant_id,'accountId',t.account_id,'importId',t.id,'approvedAt',t.approved_at,
  'previousImportId',t.definition->>'resumesImportId','recoveryMode',t.definition->'recovery'->>'mode','supersededBy',newer,
  'scope',cfg,'checkpoint',cp,'jobKey',key,'stateVersion',fingerprint,'stateValid',coalesce(valid,false),'connectionReady',coalesce(ready,false),'active',active,
  'latestJob',case when j.id is null then null else jsonb_build_object('id',j.id,'status',j.status,
   'availableAt',case when j.status in ('queued','retrying') then j.available_at else null end,
   'errorCode',case when j.error_code ~ '^slack_history_[a-z_]{1,80}$' then j.error_code else null end,
   'stopReason',case when j.result->>'stopReason' in ('window_pages_complete','page_budget_exhausted','run_page_limit','authorisation_changed') then j.result->>'stopReason' else null end) end);
end $function$

CREATE OR REPLACE FUNCTION public.slack_thread_commit_page(p_tenant_id uuid, p_job_id uuid, p_import_id uuid, p_claimed_by text, p_attempt_count integer, p_expected jsonb, p_next jsonb, p_records jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;t public.slack_thread_imports%rowtype;a public.connector_accounts%rowtype;
 cfg jsonb;scope_key jsonb;receipt jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'slack_queue_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'slack_queue_snapshot' using errcode='22023';end if;
 select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
 if not found or j.status<>'running' or j.job_type<>'slack.thread_sync' or j.payload->>'thread_import_id' is distinct from p_import_id::text
  or p_claimed_by is null or j.claimed_by is distinct from p_claimed_by or p_attempt_count is null or j.attempt_count is distinct from p_attempt_count
  or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp() then raise exception 'slack_queue_not_owned' using errcode='PT409';end if;
 receipt:=j.metadata->'slack_page_v1';
 if receipt is not null then
  if receipt->>'thread_import_id'=p_import_id::text and receipt->'expected'=p_expected and receipt->'next'=p_next and receipt->>'records_hash'=md5(p_records::text) then return true;end if;
  raise exception 'slack_page_already_committed' using errcode='PT409';
 end if;
 select * into t from public.slack_thread_imports where id=p_import_id and tenant_id=p_tenant_id for update;
 if not found or j.payload->>'connector_account_id' is distinct from t.account_id::text then raise exception 'thread_import_unavailable';end if;
 select * into a from public.connector_accounts where id=t.account_id and tenant_id=p_tenant_id for share;
 if not found or a.status<>'active' then raise exception 'thread_account_unavailable';end if;
 perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id and connector_id='slack' and enabled and status='active' for share;
 if not found then raise exception 'thread_connector_unavailable';end if;
 if not public.learn_slack_recurring_thread_allowed(p_tenant_id,t.id) then raise exception 'slack_recurring_thread_paused' using errcode='42501';end if;
 cfg:=t.scope;
 if cfg->'approved' is distinct from 'true'::jsonb or coalesce((cfg->>'expiresAt')::timestamptz,'-infinity')<=clock_timestamp() then raise exception 'thread_scope_unavailable';end if;
 perform 1 from public.provider_connections where id=(cfg->>'connectionId')::uuid and tenant_id=p_tenant_id and provider='slack'
  and status='configured' and revoked_at is null and non_secret_config->>'team_id'=cfg->>'teamId' for share;
 if not found then raise exception 'thread_connection_unavailable';end if;
 scope_key:=jsonb_build_array(p_tenant_id::text,cfg->>'teamId',cfg->>'channelId',cfg->>'oldest',cfg->>'latest',cfg->>'consentReference',cfg->>'parentTimestamp');
 if jsonb_typeof(p_expected) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object'
  or not(p_expected ?& array['scopeKey','cursor','pages','complete']) or not(p_next ?& array['scopeKey','cursor','pages','complete'])
  or (select count(*) from jsonb_object_keys(p_expected))<>4 or (select count(*) from jsonb_object_keys(p_next))<>4
  or jsonb_typeof(p_expected->'scopeKey') is distinct from 'string' or jsonb_typeof(p_next->'scopeKey') is distinct from 'string'
  or (p_expected->>'scopeKey')::jsonb is distinct from scope_key or p_next->>'scopeKey' is distinct from p_expected->>'scopeKey'
  or jsonb_typeof(p_expected->'pages') is distinct from 'number' or jsonb_typeof(p_next->'pages') is distinct from 'number'
  or (p_expected->>'pages') !~ '^[0-9]+$' or (p_next->>'pages') !~ '^[0-9]+$'
  or (p_next->>'pages')::integer<>(p_expected->>'pages')::integer+1 or (p_next->>'pages')::integer>(cfg->>'maxPages')::integer
  or p_expected->'complete' is distinct from 'false'::jsonb or jsonb_typeof(p_next->'complete') is distinct from 'boolean'
  or jsonb_typeof(p_expected->'cursor') not in ('null','string') or jsonb_typeof(p_next->'cursor') not in ('null','string')
  or p_next->'complete'='true'::jsonb and p_next->>'cursor' is not null
  or p_next->'complete'='false'::jsonb and coalesce(p_next->>'cursor','')=''
  or length(coalesce(p_next->>'cursor',''))>1024 or length(coalesce(p_expected->>'cursor',''))>1024
  or p_next->>'cursor' is not null and p_next->>'cursor'=p_expected->>'cursor' then raise exception 'thread_checkpoint_invalid';end if;
 if t.checkpoint is distinct from p_expected and not(t.checkpoint='{}'::jsonb and p_expected->'pages'='0'::jsonb and p_expected->'cursor'='null'::jsonb) then
  raise exception 'thread_checkpoint_conflict' using errcode='PT409';end if;
 perform public.learn_slack_store_records(p_tenant_id,cfg,p_records,cfg->>'parentTimestamp');
 update public.slack_thread_imports set checkpoint=p_next where id=t.id;
 update public.platform_jobs set metadata=coalesce(metadata,'{}')||jsonb_build_object('slack_page_v1',jsonb_build_object(
  'kind','thread','thread_import_id',t.id,'account_id',t.account_id,'expected',p_expected,'next',p_next,'max_pages',(cfg->>'maxPages')::integer,
  'records_hash',md5(p_records::text),'records_processed',jsonb_array_length(p_records),'committed_at',clock_timestamp())) where id=j.id;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'slack_queue_not_owned' using errcode='PT409';end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.learn_operator_capture_control_request(p_tenant uuid, p_request uuid, p_actor uuid, p_definition jsonb, p_mode text DEFAULT 'apply'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare prior public.learn_capture_control_requests%rowtype;previous jsonb;answer jsonb;k text;begin
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 if p_request is null or p_mode is null or p_mode not in ('apply','check','cancel') or jsonb_typeof(p_definition) is distinct from 'object'
  or octet_length(p_definition::text)>4000 then raise exception 'learn_capture_request_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-capture-request:'||p_request::text,0));
 select * into prior from public.learn_capture_control_requests where id=p_request;
 if found then
  if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.definition<>p_definition then
   raise exception 'learn_capture_request_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if p_mode='check' then return jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','pending');end if;
 if p_mode='cancel' then answer:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','cancelled');
 else
  if not p_definition ?& array['reason','revision','values'] or (p_definition-array['reason','revision','values'])<>'{}'::jsonb
   or jsonb_typeof(p_definition->'reason') is distinct from 'string' or length(btrim(p_definition->>'reason')) not between 1 and 1000
   or jsonb_typeof(p_definition->'revision') is distinct from 'string' or p_definition->>'revision'!~'^[a-f0-9]{32}$'
   or jsonb_typeof(p_definition->'values') is distinct from 'object' or (select count(*) from jsonb_object_keys(p_definition->'values'))<>4 then
   raise exception 'learn_capture_definition_invalid' using errcode='22023';end if;
  foreach k in array array['learn.enabled','learn.inputs.email.enabled','learn.inputs.phone.enabled','learn.inputs.slack.enabled'] loop
   if jsonb_typeof(p_definition->'values'->k) is distinct from 'boolean' then raise exception 'learn_capture_flags_invalid' using errcode='22023';end if;
  end loop;
  -- Same lock as existing Commusoft/master controls; concurrent operator edits cannot
  -- silently overwrite each other's master switch or admit a batch mid-update.
  perform pg_advisory_xact_lock(hashtextextended('learn-input-setup:'||p_tenant::text,0));
  previous:=public.learn_capture_control_state(p_tenant);
  if previous->>'revision' is distinct from p_definition->>'revision' then raise exception 'learn_capture_flags_changed' using errcode='PT409';end if;
  foreach k in array array['learn.enabled','learn.inputs.email.enabled','learn.inputs.phone.enabled','learn.inputs.slack.enabled'] loop
   update public.feature_flags set value=p_definition->'values'->k where tenant_id=p_tenant and flag=k;
   if not found then insert into public.feature_flags(tenant_id,flag,value) values(p_tenant,k,p_definition->'values'->k);end if;
  end loop;
  answer:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','recorded','controls',public.learn_capture_control_state(p_tenant));
 end if;
 insert into public.learn_capture_control_requests(id,tenant_id,actor_id,definition,receipt,previous_state)
  values(p_request,p_tenant,p_actor,p_definition,answer,previous);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_phone_capture_flag_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare old_tenant uuid;new_tenant uuid;t uuid;
begin
 if TG_OP<>'INSERT' and OLD.flag in ('learn.enabled','learn.inputs.phone.enabled') then old_tenant:=OLD.tenant_id;end if;
 if TG_OP<>'DELETE' and NEW.flag in ('learn.enabled','learn.inputs.phone.enabled') then new_tenant:=NEW.tenant_id;end if;
 for t in select distinct v from unnest(array[old_tenant,new_tenant])v where v is not null order by v loop
  perform pg_advisory_xact_lock(hashtextextended('learn-input-setup:'||t::text,0));
 end loop;
 if TG_OP='DELETE' then return OLD;end if;return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.learn_phone_complete_import(p_tenant uuid, p_run uuid, p_account uuid, p_connector uuid, p_customer text, p_kind text, p_pages integer, p_records integer, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.phone_sync_runs%rowtype;a public.connector_accounts%rowtype;c public.tenant_connectors%rowtype;
 prior public.learn_phone_import_completions%rowtype;d jsonb;scope jsonb;answer jsonb;
 page_count integer;last_page integer;record_count integer;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'phone_completion_snapshot_invalid' using errcode='22023';end if;
 if p_tenant is null or p_run is null or p_account is null or p_connector is null or p_customer is null
 or p_customer!~'^[A-Za-z0-9_-]{1,128}$' or p_kind is null or p_kind not in ('calls','recordings')
 or p_pages is null or p_pages not between 1 and 50 or p_records is null or p_records not between 0 and 10000
 or jsonb_typeof(p_metadata) is distinct from 'object' or octet_length(p_metadata::text)>16384
 or p_metadata->'window_complete' is distinct from 'true'::jsonb
 or p_metadata->'pages_fetched' is distinct from to_jsonb(p_pages)
 or p_metadata->>'customer_id' is distinct from p_customer
 or p_metadata->(case when p_kind='calls' then 'skipped_no_call_id' else 'skipped_no_recording_id' end) is distinct from '0'::jsonb then
  raise exception 'phone_completion_invalid' using errcode='22023';end if;
 scope:=jsonb_build_object('accountId',p_account,'connectorId',p_connector,'customerId',p_customer,'kind',p_kind);
 d:=scope||jsonb_build_object('pages',p_pages,'recordsProcessed',p_records,'metadata',p_metadata);
 -- Same ordering as publication/controller: controller lock, run, tenant,
 -- connector, account. An exact receipt replay is read-only even after a pause.
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 select * into r from public.phone_sync_runs where id=p_run and tenant_id=p_tenant for update;
 if not found or r.provider<>'simwood' or r.sync_type<>p_kind then raise exception 'phone_completion_run_changed' using errcode='PT409';end if;
 select * into prior from public.learn_phone_import_completions where run_id=p_run;
 if found then
  if prior.tenant_id<>p_tenant or prior.definition<>d then raise exception 'phone_completion_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if r.status<>'running' then raise exception 'phone_completion_run_changed' using errcode='PT409';end if;
 if jsonb_typeof(r.metadata->'from') is distinct from 'string' or jsonb_typeof(r.metadata->'to') is distinct from 'string'
 or not (p_metadata @> r.metadata) or not isfinite((r.metadata->>'from')::timestamptz)
 or not isfinite((r.metadata->>'to')::timestamptz) or (r.metadata->>'from')::timestamptz >= (r.metadata->>'to')::timestamptz then
  raise exception 'phone_completion_window_changed' using errcode='PT409';end if;
 select count(*),max(page),coalesce(sum((receipt->>'recordsProcessed')::integer),0)
 into page_count,last_page,record_count from public.learn_phone_capture_pages where run_id=p_run;
 if page_count<>p_pages or last_page is distinct from p_pages or record_count<>p_records
 or exists(select 1 from public.learn_phone_capture_pages where run_id=p_run
  and (tenant_id<>p_tenant or (definition-'recordsSha256')<>scope)) then
  raise exception 'phone_completion_pages_changed' using errcode='PT409';end if;
 perform 1 from public.tenants where id=p_tenant and status='active' for share;
 if not found or not public.learn_capture_allowed(p_tenant,'phone') then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 select * into c from public.tenant_connectors where id=p_connector and tenant_id=p_tenant for share;
 if not found or c.connector_id<>'simwood' or c.provider<>'simwood' or not c.enabled or c.status not in ('active','error') then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 select * into a from public.connector_accounts where id=p_account and tenant_id=p_tenant for share;
 if not found or a.tenant_connector_id<>p_connector or a.status<>'active'
 or coalesce(nullif(btrim(a.settings->>'provider_customer_id'),''),a.account_key) is distinct from p_customer then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 answer:=scope||jsonb_build_object('version','learn-phone-import/1','tenantId',p_tenant,'runId',p_run,
  'pages',p_pages,'recordsProcessed',p_records,'from',r.metadata->>'from','to',r.metadata->>'to','windowComplete',true);
 update public.phone_sync_runs set status='success',completed_at=clock_timestamp(),records_processed=p_records,
  error_message=null,metadata=p_metadata where id=p_run and tenant_id=p_tenant;
 insert into public.learn_phone_import_completions(run_id,tenant_id,definition,receipt) values(p_run,p_tenant,d,answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_phone_publish_page(p_tenant uuid, p_run uuid, p_account uuid, p_connector uuid, p_customer text, p_kind text, p_page integer, p_records jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.phone_sync_runs%rowtype;a public.connector_accounts%rowtype;c public.tenant_connectors%rowtype;
 prior public.learn_phone_capture_pages%rowtype;d jsonb;answer jsonb;item jsonb;identity_key text;keys text[];
 inserted_id uuid;new_ids jsonb:='[]'::jsonb;previous_page integer;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'phone_page_snapshot_invalid' using errcode='22023';end if;
 if p_tenant is null or p_run is null or p_account is null or p_connector is null or p_customer is null
 or p_customer!~'^[A-Za-z0-9_-]{1,128}$' or p_kind is null or p_kind not in ('calls','recordings')
 or p_page is null or p_page not between 1 and 50 or jsonb_typeof(p_records) is distinct from 'array'
 or jsonb_array_length(p_records)>200 or octet_length(p_records::text)>2097152 then
  raise exception 'phone_page_invalid' using errcode='22023';end if;
 identity_key:=case when p_kind='calls' then 'provider_call_id' else 'provider_recording_id' end;
 keys:=case when p_kind='calls' then array['tenant_id','provider','provider_call_id','linked_id','direction','from_number','to_number','started_at','duration_seconds','outcome','cost','raw_payload']
  else array['tenant_id','provider','provider_recording_id','provider_call_id','linked_id','recording_uri','file_size','started_at','duration_seconds','raw_payload'] end;
 if exists(select 1 from jsonb_array_elements(p_records)x where jsonb_typeof(x) is distinct from 'object'
  or x->>'tenant_id' is distinct from p_tenant::text or x->>'provider' is distinct from 'simwood'
  or jsonb_typeof(x->identity_key) is distinct from 'string' or length(btrim(x->>identity_key)) not between 1 and 200
  or (x-keys)<>'{}'::jsonb or jsonb_typeof(x->'raw_payload') is distinct from 'object')
 or (select count(distinct x->>identity_key) from jsonb_array_elements(p_records)x)<>jsonb_array_length(p_records) then
  raise exception 'phone_page_records_invalid' using errcode='22023';end if;
 d:=jsonb_build_object('accountId',p_account,'connectorId',p_connector,'customerId',p_customer,'kind',p_kind,
  'recordsSha256',encode(sha256(convert_to(p_records::text,'UTF8')),'hex'));
 -- Lock order shared with controller changes, then the run. Replays only read a receipt.
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 select * into r from public.phone_sync_runs where id=p_run and tenant_id=p_tenant for update;
 if not found or r.provider<>'simwood' or r.sync_type<>p_kind then raise exception 'phone_page_run_changed' using errcode='PT409';end if;
 select * into prior from public.learn_phone_capture_pages where run_id=p_run and page=p_page;
 if found then
  if prior.tenant_id<>p_tenant or prior.definition<>d then raise exception 'phone_page_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if r.status<>'running' then raise exception 'phone_page_run_changed' using errcode='PT409';end if;
 select max(page) into previous_page from public.learn_phone_capture_pages where run_id=p_run;
 if p_page<>coalesce(previous_page,0)+1 or exists(select 1 from public.learn_phone_capture_pages where run_id=p_run
  and (definition-'recordsSha256')<>(d-'recordsSha256')) then raise exception 'phone_page_sequence_changed' using errcode='PT409';end if;
 -- Native row locks fence direct tenant/account/connector changes through commit.
 perform 1 from public.tenants where id=p_tenant and status='active' for share;
 if not found or not public.learn_capture_allowed(p_tenant,'phone') then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 select * into c from public.tenant_connectors where id=p_connector and tenant_id=p_tenant for share;
 if not found or c.connector_id<>'simwood' or c.provider<>'simwood' or not c.enabled or c.status not in ('active','error') then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 select * into a from public.connector_accounts where id=p_account and tenant_id=p_tenant for share;
 if not found or a.tenant_connector_id<>p_connector or a.status<>'active'
 or coalesce(nullif(btrim(a.settings->>'provider_customer_id'),''),a.account_key) is distinct from p_customer then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 -- Stable source-key order avoids deadlocks between concurrent pages/runs.
 for item in select x from jsonb_array_elements(p_records)x order by x->>identity_key loop
  if p_kind='calls' then
   insert into public.phone_calls(tenant_id,provider,provider_call_id,linked_id,direction,from_number,to_number,started_at,duration_seconds,outcome,cost,raw_payload)
   values(p_tenant,'simwood',item->>'provider_call_id',item->>'linked_id',item->>'direction',item->>'from_number',item->>'to_number',
    (item->>'started_at')::timestamptz,(item->>'duration_seconds')::integer,item->>'outcome',(item->>'cost')::numeric,item->'raw_payload')
   on conflict(tenant_id,provider,provider_call_id) do update set linked_id=excluded.linked_id,direction=excluded.direction,
    from_number=excluded.from_number,to_number=excluded.to_number,started_at=excluded.started_at,duration_seconds=excluded.duration_seconds,
    outcome=excluded.outcome,cost=excluded.cost,raw_payload=excluded.raw_payload;
  else
   inserted_id:=null;
   insert into public.phone_recordings(tenant_id,provider,provider_recording_id,provider_call_id,linked_id,recording_uri,file_size,started_at,duration_seconds,raw_payload)
   values(p_tenant,'simwood',item->>'provider_recording_id',item->>'provider_call_id',item->>'linked_id',item->>'recording_uri',
    (item->>'file_size')::bigint,(item->>'started_at')::timestamptz,(item->>'duration_seconds')::integer,item->'raw_payload')
   on conflict(tenant_id,provider,provider_recording_id) do nothing returning id into inserted_id;
   if inserted_id is not null then new_ids:=new_ids||jsonb_build_array(inserted_id);
   else
    update public.phone_recordings set provider_call_id=item->>'provider_call_id',linked_id=item->>'linked_id',recording_uri=item->>'recording_uri',
     file_size=(item->>'file_size')::bigint,started_at=(item->>'started_at')::timestamptz,duration_seconds=(item->>'duration_seconds')::integer,
     raw_payload=item->'raw_payload' where tenant_id=p_tenant and provider='simwood' and provider_recording_id=item->>'provider_recording_id';
   end if;
  end if;
 end loop;
 answer:=jsonb_build_object('version','learn-phone-page/1','tenantId',p_tenant,'runId',p_run,'page',p_page,'kind',p_kind,
  'recordsProcessed',jsonb_array_length(p_records),'newRecordingIds',new_ids);
 insert into public.learn_phone_capture_pages(run_id,page,tenant_id,definition,receipt) values(p_run,p_page,p_tenant,d,answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_phone_settle_schedule(p_tenant uuid, p_run uuid, p_calls uuid, p_recordings uuid, p_outcome text, p_errors jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.phone_sync_runs%rowtype;child public.phone_sync_runs%rowtype;j public.platform_jobs%rowtype;
 a public.connector_accounts%rowtype;c public.tenant_connectors%rowtype;prior public.learn_phone_schedule_settlements%rowtype;
 proof public.learn_phone_import_completions%rowtype;d jsonb;answer jsonb;scope jsonb;child_id uuid;k text;
 account_id uuid;connector uuid;job uuid;customer text;owner text;counts jsonb:='{}';n integer;
 window_from timestamptz;window_to timestamptz;cursor_at timestamptz;health text;checked_at timestamptz:=clock_timestamp();
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'phone_schedule_snapshot_invalid' using errcode='22023';end if;
 if p_tenant is null or p_run is null or p_outcome is null or p_outcome not in ('success','failed','paused')
 or jsonb_typeof(p_errors) is distinct from 'object' or octet_length(p_errors::text)>512 then
  raise exception 'phone_schedule_invalid' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(p_errors)e where e.key not in ('calls','recordings') or jsonb_typeof(e.value)<>'string' or e.value#>>'{}' !~ '^[a-z][a-z0-9_]{0,79}$')
 or (p_outcome='success' and (p_errors<>'{}' or p_calls is null or p_recordings is null))
 or (p_outcome<>'success' and p_errors='{}')
 or (p_outcome='paused' and exists(select 1 from jsonb_each_text(p_errors)e where e.value not in ('learn_capture_paused','learn_capture_unavailable'))) then
  raise exception 'phone_schedule_invalid' using errcode='22023';end if;
 d:=jsonb_build_object('callsRunId',p_calls,'recordingsRunId',p_recordings,'outcome',p_outcome,'errors',p_errors);
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 select * into r from public.phone_sync_runs where id=p_run and tenant_id=p_tenant for update;
 if not found or r.provider<>'simwood' or r.sync_type<>'scheduled_sync' then raise exception 'phone_schedule_run_changed' using errcode='PT409';end if;
 select * into prior from public.learn_phone_schedule_settlements where run_id=p_run;
 if found then
  if prior.tenant_id<>p_tenant or prior.definition<>d then raise exception 'phone_schedule_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if r.status<>'running' then raise exception 'phone_schedule_run_changed' using errcode='PT409';end if;
 account_id:=(r.metadata->>'connector_account_id')::uuid;connector:=(r.metadata->>'tenant_connector_id')::uuid;
 job:=(r.metadata->>'job_id')::uuid;owner:=r.metadata->>'job_owner';customer:=r.metadata->>'provider_customer_id';
 window_from:=(r.metadata->>'from')::timestamptz;window_to:=(r.metadata->>'to')::timestamptz;
 if account_id is null or connector is null or job is null or owner is null or owner='' or customer is null
 or window_from is null or window_to is null or not isfinite(window_from) or not isfinite(window_to) or window_from>=window_to
 or jsonb_typeof(r.metadata->'include_local') is distinct from 'boolean' or r.metadata->>'account_updated_at' is null then
  raise exception 'phone_schedule_scope_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where id=job and tenant_id=p_tenant for update;
 if not found or j.job_type<>'phone.scheduled_sync' or j.connector_id is distinct from 'simwood' or j.status<>'running'
 or j.claimed_by is distinct from owner or j.attempt_count<>1 or j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp()
 or j.payload->>'provider_customer_id' is distinct from customer or j.payload->>'from' is distinct from r.metadata->>'from'
 or j.payload->>'to' is distinct from r.metadata->>'to' then raise exception 'phone_schedule_job_changed' using errcode='PT409';end if;
 -- Successful children require an immutable completion receipt, matching filters
 -- and the same time window. Counts come from saved pages, never HTTP claims.
 foreach k in array array['calls','recordings'] loop
  child_id:=case when k='calls' then p_calls else p_recordings end;n:=0;
  if child_id is not null then
   select * into child from public.phone_sync_runs where id=child_id and tenant_id=p_tenant for share;
   if not found or child.provider<>'simwood' or child.sync_type<>k
   or child.metadata->>'from' is distinct from r.metadata->>'from' or child.metadata->>'to' is distinct from r.metadata->>'to' then
    raise exception 'phone_schedule_child_changed' using errcode='PT409';end if;
   scope:=jsonb_build_object('accountId',account_id,'connectorId',connector,'customerId',customer,'kind',k);
   if exists(select 1 from public.learn_phone_capture_pages where run_id=child_id and (tenant_id<>p_tenant or definition-'recordsSha256'<>scope)) then
    raise exception 'phone_schedule_child_changed' using errcode='PT409';end if;
   select coalesce(sum((receipt->>'recordsProcessed')::integer),0) into n from public.learn_phone_capture_pages where run_id=child_id;
   if not (p_errors ? k) then
    select * into proof from public.learn_phone_import_completions where run_id=child_id and tenant_id=p_tenant;
    if not found or child.status<>'success' or proof.receipt->>'version' is distinct from 'learn-phone-import/1'
    or proof.receipt->'windowComplete' is distinct from 'true'::jsonb or proof.definition-(array['pages','recordsProcessed','metadata'])<>scope
    or proof.definition->'metadata' is distinct from child.metadata or proof.receipt->>'from' is distinct from r.metadata->>'from'
    or proof.receipt->>'to' is distinct from r.metadata->>'to' or proof.receipt->'recordsProcessed' is distinct from to_jsonb(n)
    or child.metadata->'limit' is distinct from 'null'::jsonb
    or (k='calls' and (child.metadata->'direction' is distinct from 'null'::jsonb or child.metadata->'include_local' is distinct from r.metadata->'include_local'))
    or (k='recordings' and (child.metadata->'call_id' is distinct from 'null'::jsonb or child.metadata->'linked_id' is distinct from 'null'::jsonb)) then
     raise exception 'phone_schedule_child_unconfirmed' using errcode='PT409';end if;
   end if;
  elsif not (p_errors ? k) then raise exception 'phone_schedule_child_unconfirmed' using errcode='PT409';
  end if;
  counts:=counts||jsonb_build_object(k,n);
 end loop;
 perform 1 from public.tenants where id=p_tenant and status='active' for share;
 if not found then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 if p_outcome='success' and not public.learn_capture_allowed(p_tenant,'phone') then raise exception 'learn_capture_paused' using errcode='PT409';end if;
 select * into c from public.tenant_connectors where id=connector and tenant_id=p_tenant for update;
 if not found or c.connector_id<>'simwood' or c.provider<>'simwood' or not c.enabled or c.status not in ('active','error') then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 select * into a from public.connector_accounts where id=account_id and tenant_id=p_tenant for update;
 if not found or a.tenant_connector_id<>connector or a.status<>'active'
 or coalesce(nullif(btrim(a.settings->>'provider_customer_id'),''),a.account_key) is distinct from customer then
  raise exception 'phone_account_unavailable' using errcode='PT409';end if;
 if a.updated_at is distinct from (r.metadata->>'account_updated_at')::timestamptz
 or coalesce(a.settings->'include_local_calls'='true'::jsonb,false) is distinct from (r.metadata->>'include_local')::boolean then
  raise exception 'phone_schedule_account_changed' using errcode='PT409';end if;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'phone_schedule_job_changed' using errcode='PT409';end if;
 if jsonb_typeof(a.sync_cursor) is distinct from 'object' then raise exception 'phone_schedule_cursor_invalid' using errcode='PT409';end if;
 cursor_at:=coalesce((a.sync_cursor->>'last_synced_until')::timestamptz,a.last_successful_sync_at);
 if p_outcome='success' then
  if (cursor_at is not null and (not isfinite(cursor_at) or window_from>cursor_at or window_to<cursor_at))
  or (cursor_at is null and window_from>window_to-interval '24 hours') then raise exception 'phone_schedule_window_gap' using errcode='PT409';end if;
  update public.connector_accounts set sync_cursor=sync_cursor||jsonb_build_object('last_synced_until',r.metadata->>'to'),
   last_successful_sync_at=window_to,last_error=null where id=account_id;
  -- One successful account must not hide another account's missing/failed sync.
  health:=case when exists(select 1 from public.connector_accounts where tenant_connector_id=connector and tenant_id=p_tenant
   and status='active' and (last_successful_sync_at is null or last_error is not null)) then 'warning' else 'healthy' end;
  update public.tenant_connectors set last_successful_sync_at=greatest(last_successful_sync_at,window_to),health_status=health,
   last_error=case when health='healthy' then null else 'phone_accounts_need_attention' end where id=connector;
 elsif p_outcome='failed' then
  update public.connector_accounts set last_failed_sync_at=checked_at,last_error='phone_sync_failed' where id=account_id;
  update public.tenant_connectors set last_failed_sync_at=checked_at,health_status='warning',last_error='phone_sync_failed' where id=connector;
 end if;
 answer:=jsonb_build_object('version','learn-phone-schedule/1','tenantId',p_tenant,'runId',p_run,'accountId',account_id,
  'connectorId',connector,'customerId',customer,'jobId',job,'outcome',p_outcome,'callsRunId',p_calls,'recordingsRunId',p_recordings,
  'callsProcessed',counts->'calls','recordingsProcessed',counts->'recordings','from',r.metadata->>'from','to',r.metadata->>'to',
  'cursorAdvanced',p_outcome='success');
 n:=(counts->>'calls')::integer+(counts->>'recordings')::integer;
 update public.phone_sync_runs set status=p_outcome,completed_at=checked_at,records_processed=n,
  error_message=case when p_outcome='failed' then 'phone_sync_failed' else null end,
  metadata=metadata||jsonb_build_object('calls_sync_run_id',p_calls,'recordings_sync_run_id',p_recordings,
   'calls_processed',counts->'calls','recordings_processed',counts->'recordings','errors',p_errors,'settlement',answer) where id=p_run;
 update public.platform_jobs set status=case p_outcome when 'success' then 'succeeded' when 'paused' then 'cancelled' else 'failed' end,
  completed_at=checked_at,failed_at=case when p_outcome='failed' then checked_at else failed_at end,
  cancelled_at=case when p_outcome='paused' then checked_at else cancelled_at end,
  last_error=case when p_outcome='failed' then 'phone_sync_failed' else null end,records_processed=n,progress_current=n,
  error_count=case when p_outcome='failed' then 1 else 0 end,
  result=answer||jsonb_build_object('capture_waiting',p_outcome='paused'),lease_expires_at=null where id=job;
 insert into public.learn_phone_schedule_settlements(run_id,tenant_id,definition,receipt) values(p_run,p_tenant,d,answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_commusoft_acquire_page(p_tenant_id uuid, p_job_id uuid, p_claimed_by text, p_attempt_count integer, p_expected jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  j public.platform_jobs%rowtype;
  a public.connector_accounts%rowtype;
  c public.provider_connections%rowtype;
  cfg jsonb; cp jsonb; req jsonb; target jsonb; pages integer; after_id bigint; flag_name text;
  secret text; fingerprint text; next_at timestamptz; permit_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'commusoft_permit_forbidden' using errcode='42501';
  end if;
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'commusoft_permit_snapshot' using errcode='22023';
  end if;
  if p_tenant_id is null or p_job_id is null or nullif(btrim(p_claimed_by),'') is null
     or p_attempt_count is null or p_attempt_count<1 or jsonb_typeof(p_expected) is distinct from 'object'
     or p_expected->>'tenantId' is distinct from p_tenant_id::text
     or p_expected->>'jobId' is distinct from p_job_id::text then return null; end if;

  select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
  if not found or j.job_type is distinct from 'commusoft.source_sync' or j.status is distinct from 'running'
     or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_attempt_count
     or coalesce(j.lease_expires_at,'-infinity')<=clock_timestamp() then return null; end if;
  perform 1 from public.tenants where id=p_tenant_id and status='active' for share;
  if not found then return null; end if;
  foreach flag_name in array array['learn.enabled','learn.inputs.commusoft.enabled'] loop
    perform 1 from public.feature_flags where tenant_id=p_tenant_id and flag=flag_name and value='true'::jsonb for share;
    if not found then return null; end if;
  end loop;
  select * into a from public.connector_accounts where id::text=j.payload->>'connector_account_id'
    and tenant_id=p_tenant_id for share;
  if not found or a.status is distinct from 'active' or a.id::text is distinct from p_expected->>'accountId'
     or nullif(btrim(a.account_key),'') is null or length(a.account_key)>2000
     or a.tenant_connector_id::text is distinct from p_expected->>'connectorId'
     or a.sync_cursor is distinct from p_expected->'checkpoint' then return null; end if;
  perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id
    and connector_id='commusoft' and provider='commusoft' and enabled and status='active' for share;
  if not found then return null; end if;
  cfg:=a.settings->'commusoft_import';
  if jsonb_typeof(cfg) is distinct from 'object' or cfg is distinct from p_expected->'approval'
     or cfg->'approved' is distinct from 'true'::jsonb
     or (cfg->>'approvalId')::uuid is null or (cfg->>'connectionId')::uuid is null
     or nullif(btrim(cfg->>'consentReference'),'') is null or length(cfg->>'consentReference')>2000
     or coalesce((cfg->>'expiresAt')::timestamptz,'-infinity')<=clock_timestamp()
     or jsonb_typeof(cfg->'maxPages') is distinct from 'number' or (cfg->>'maxPages')::integer not between 1 and 2147483647
     or jsonb_typeof(cfg->'pageSize') is distinct from 'number' or (cfg->>'pageSize')::integer not between 1 and 100
     or coalesce(cfg->>'resource','') not in ('properties','propertyContacts','jobs') then return null; end if;
  if cfg->>'resource'='propertyContacts' then
    if coalesce(cfg->>'contactType','') not in ('customer','workaddress') then return null; end if;
  elsif cfg ? 'contactType' then return null; end if;

  if j.job_key is distinct from 'commusoft.source:'||a.id::text||':'||(cfg->>'approvalId') then return null;end if;
  select * into c from public.provider_connections where id=(cfg->>'connectionId')::uuid and tenant_id=p_tenant_id for share;
  if not found or c.id::text is distinct from p_expected->>'connectionId' or c.provider is distinct from 'commusoft'
     or c.status is distinct from 'configured' or c.auth_mode is distinct from 'private_api_key'
     or c.revoked_at is not null or c.verified_at is null or c.verified_at>clock_timestamp()
     or c.updated_at is null or c.updated_at is distinct from (p_expected->>'connectionRevision')::timestamptz
     or coalesce(c.non_secret_config->>'region','') not in ('uk','us')
     or c.non_secret_config->>'account_key' is distinct from a.account_key
     or not coalesce('api_key'=any(c.configured_fields),false)
     or c.secret_refs->>'api_key' is distinct from p_expected->>'secretId' then return null; end if;

  cp:=a.sync_cursor;
  if cp='{}'::jsonb then cp:=jsonb_build_object('approvalId',cfg->>'approvalId','after',null,'pages',0,'complete',false); end if;
  if jsonb_typeof(cp) is distinct from 'object' or cp->>'approvalId' is distinct from cfg->>'approvalId'
     or jsonb_typeof(cp->'pages') is distinct from 'number' or cp->'complete' is distinct from 'false'::jsonb then return null; end if;
  pages:=(cp->>'pages')::integer;
  if pages<0 or pages>=(cfg->>'maxPages')::integer then return null; end if;
  if cp->'after'='null'::jsonb then after_id:=null;
  elsif jsonb_typeof(cp->'after')='number' then after_id:=(cp->>'after')::bigint;
  else return null; end if;
  if pages=0 and after_id is not null or pages>0 and after_id is null and cfg->>'resource'<>'propertyContacts'
   or after_id is not null and (after_id<1 or after_id>9007199254740991) then return null;end if;
  req:=jsonb_build_object('region',c.non_secret_config->>'region','resource',cfg->>'resource','after',after_id,'limit',(cfg->>'pageSize')::integer);
  if cfg->>'resource'='propertyContacts' then
   target:=public.learn_commusoft_contact_target(p_tenant_id,c.id,cfg,a.sync_cursor);
   if target is null or target is distinct from p_expected->'contactTarget' then return null;end if;
   req:=req||jsonb_build_object('contactType',cfg->>'contactType','propertyId',target->'propertyId');
  end if;
  if req is distinct from p_expected->'request' or p_expected->'pages' is distinct from to_jsonb(pages)
     or p_expected->'complete' is distinct from 'false'::jsonb then return null; end if;

  if coalesce(j.metadata,'{}'::jsonb) ? 'commusoft_page_v1' then return null;end if;
  -- A repeated acquisition cannot release a second credential for this attempt.
  -- An uncertain response is not retried inline; recovery uses a new queue attempt.
  if exists(select 1 from public.learn_business_input_request_permits where job_id=j.id and attempt_count=p_attempt_count) then return null; end if;
  select decrypted_secret into secret from vault.decrypted_secrets
    where id=(c.secret_refs->>'api_key')::uuid and name='provider_secret:'||p_tenant_id::text||':commusoft:api_key';
  if secret is null or length(secret) not between 1 and 4096 or secret !~ '^[!-~]+$' then return null; end if;
  -- The same key stored in different tenant Vault entries still shares quota.
  -- Fingerprints are infrastructure-private, never returned to a worker/client.
  fingerprint:=encode(sha256(convert_to('commusoft:'||secret,'UTF8')),'hex');
  insert into public.learn_business_input_request_gates values(fingerprint,clock_timestamp()) on conflict do nothing;
  select next_allowed_at into next_at from public.learn_business_input_request_gates
    where credential_fingerprint=fingerprint for update;
  if j.lease_expires_at<=clock_timestamp() or (cfg->>'expiresAt')::timestamptz<=clock_timestamp() then return null; end if;
  if next_at>clock_timestamp() then
    return jsonb_build_object('state','wait','retryAt',ceil(extract(epoch from next_at)*1000)::bigint);
  end if;
  -- 48 reservations/minute leaves room below the documented 60/minute ceiling.
  update public.learn_business_input_request_gates set next_allowed_at=clock_timestamp()+interval '1250 milliseconds'
    where credential_fingerprint=fingerprint;
  insert into public.learn_business_input_request_permits(tenant_id,job_id,claimed_by,attempt_count,binding,credential_fingerprint)
    values(p_tenant_id,p_job_id,p_claimed_by,p_attempt_count,
      jsonb_build_object('accountId',a.id,'connectorId',a.tenant_connector_id,'connectionId',c.id,
        'connectionRevision',c.updated_at,'secretId',c.secret_refs->>'api_key',
        'approval',cfg,'checkpoint',a.sync_cursor,'request',req),fingerprint) returning id into permit_id;
  -- Short send window prevents delayed workers banking reservations for a burst.
  return jsonb_build_object('state','ready','apiKey',secret,'permitId',permit_id,
    'sendBefore',floor(extract(epoch from clock_timestamp()+interval '5 seconds')*1000)::bigint);
end $function$

CREATE OR REPLACE FUNCTION public.learn_commusoft_commit_page(p_tenant_id uuid, p_job_id uuid, p_claimed_by text, p_attempt_count integer, p_permit_id uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  permit public.learn_business_input_request_permits%rowtype;
  prior public.learn_business_input_pages%rowtype;
  j public.platform_jobs%rowtype;
  a public.connector_accounts%rowtype;
  connection public.provider_connections%rowtype;
  b jsonb; cfg jsonb; cp jsonb; target jsonb; next_cp jsonb; receipt jsonb; flag_name text;
  page_id uuid; version_id uuid; item jsonb; item_id bigint; previous_id bigint; next_id bigint;
  n integer:=0; pages integer; has_more boolean; v_hash text; saved_payload jsonb;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'commusoft_publication_forbidden' using errcode='42501';end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'commusoft_publication_snapshot' using errcode='22023';end if;
  -- Serialize against acquisition and concurrent/repeated publication for this job.
  select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'commusoft_job_unavailable' using errcode='42501';end if;
  select * into permit from public.learn_business_input_request_permits where id=p_permit_id and tenant_id=p_tenant_id
    and job_id=p_job_id and claimed_by=p_claimed_by and attempt_count=p_attempt_count;
  if not found then raise exception 'commusoft_permit_unavailable' using errcode='42501';end if;
  select * into prior from public.learn_business_input_pages where permit_id=p_permit_id;
  if found then
    if prior.envelope is distinct from p_envelope then raise exception 'commusoft_page_conflict' using errcode='PT409';end if;
    -- Exact replay acknowledges retained data without changing it or acquiring authority.
    return jsonb_build_object('pageId',prior.id,'checkpoint',prior.checkpoint_after,'records',prior.record_count,'already',true);
  end if;
  if j.job_type is distinct from 'commusoft.source_sync' or j.status is distinct from 'running'
    or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_attempt_count
    or coalesce(j.lease_expires_at,'-infinity')<=clock_timestamp()
    or coalesce(j.metadata,'{}'::jsonb) ? 'commusoft_page_v1' then raise exception 'commusoft_job_unavailable' using errcode='42501';end if;
  perform 1 from public.tenants where id=p_tenant_id and status='active' for share;
  if not found then raise exception 'commusoft_tenant_unavailable' using errcode='42501';end if;
  foreach flag_name in array array['learn.enabled','learn.inputs.commusoft.enabled'] loop
    perform 1 from public.feature_flags where tenant_id=p_tenant_id and flag=flag_name and value='true'::jsonb for share;
    if not found then raise exception 'commusoft_module_unavailable' using errcode='42501';end if;
  end loop;
  b:=permit.binding; cfg:=b->'approval'; cp:=b->'checkpoint';
  if j.job_key is distinct from 'commusoft.source:'||(b->>'accountId')||':'||(cfg->>'approvalId') then raise exception 'commusoft_queue_identity' using errcode='PT409';end if;
  select * into a from public.connector_accounts where id::text=b->>'accountId' and tenant_id=p_tenant_id for update;
  if not found or a.id::text is distinct from j.payload->>'connector_account_id' or a.status is distinct from 'active'
    or a.tenant_connector_id::text is distinct from b->>'connectorId'
    or a.settings->'commusoft_import' is distinct from cfg or a.sync_cursor is distinct from cp
    or coalesce((cfg->>'expiresAt')::timestamptz,'-infinity')<=clock_timestamp() then
    raise exception 'commusoft_scope_changed' using errcode='PT409';end if;
  perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id
    and connector_id='commusoft' and provider='commusoft' and enabled and status='active' for share;
  if not found then raise exception 'commusoft_connector_unavailable' using errcode='42501';end if;
  select * into connection from public.provider_connections where id::text=b->>'connectionId' and tenant_id=p_tenant_id for share;
  if not found or connection.provider is distinct from 'commusoft' or connection.status is distinct from 'configured'
    or connection.auth_mode is distinct from 'private_api_key' or connection.revoked_at is not null
    or connection.verified_at is null or connection.verified_at>clock_timestamp()
    or connection.updated_at is distinct from (b->>'connectionRevision')::timestamptz
    or connection.non_secret_config->>'account_key' is distinct from a.account_key
    or connection.non_secret_config->>'region' is distinct from b->'request'->>'region'
    or not coalesce('api_key'=any(connection.configured_fields),false)
    or connection.secret_refs->>'api_key' is distinct from b->>'secretId' then
    raise exception 'commusoft_connection_changed' using errcode='42501';end if;

  if cfg->>'resource'='propertyContacts' then
   target:=public.learn_commusoft_contact_target(p_tenant_id,connection.id,cfg,cp);
   if target is null or b->'request'->'propertyId' is distinct from target->'propertyId' then raise exception 'commusoft_contact_scope_changed' using errcode='PT409';end if;
  end if;

  if jsonb_typeof(p_envelope) is distinct from 'object' or octet_length(p_envelope::text)>4194304
    or jsonb_typeof(p_envelope->'data') is distinct from 'array'
    or jsonb_array_length(p_envelope->'data')>(b->'request'->>'limit')::integer
    or jsonb_typeof(p_envelope->'pagination') is distinct from 'object'
    or jsonb_typeof(p_envelope->'pagination'->'hasMore') is distinct from 'boolean' then
    raise exception 'commusoft_page_invalid' using errcode='22023';end if;
  has_more:=(p_envelope->'pagination'->>'hasMore')::boolean;
  previous_id:=coalesce((b->'request'->>'after')::bigint,0);
  pages:=case when cp='{}'::jsonb then 0 else (cp->>'pages')::integer end;
  next_cp:=jsonb_build_object('approvalId',cfg->>'approvalId','after',null,'pages',pages+1,'complete',not has_more);
  page_id:=gen_random_uuid();
  -- Stage checkpoint in a local variable; immutable page is inserted after validation.
  for item in select value from jsonb_array_elements(p_envelope->'data') loop
    if jsonb_typeof(item) is distinct from 'object' or octet_length(item::text)>524288
      or jsonb_typeof(item->'id') is distinct from 'number' or (item->>'id') !~ '^[0-9]+$' then
      raise exception 'commusoft_record_invalid' using errcode='22023';end if;
    if cfg->>'resource'='propertyContacts' and item->'propertyID' is distinct from target->'propertyId' then
     raise exception 'commusoft_contact_parent_mismatch' using errcode='22023';end if;
    item_id:=(item->>'id')::bigint;
    if item_id<=previous_id or item_id>9007199254740991 then raise exception 'commusoft_record_order_invalid' using errcode='22023';end if;
    previous_id:=item_id; n:=n+1;
  end loop;
  if p_envelope->'pagination'->'nextCursor' is null or p_envelope->'pagination'->'nextCursor'='null'::jsonb then next_id:=null;
  elsif jsonb_typeof(p_envelope->'pagination'->'nextCursor')='number' and p_envelope->'pagination'->>'nextCursor' ~ '^[0-9]+$' then
    next_id:=(p_envelope->'pagination'->>'nextCursor')::bigint;
  else raise exception 'commusoft_cursor_invalid' using errcode='22023';end if;
  if has_more and (n=0 or next_id is null or next_id<>previous_id) or
     not has_more and next_id is not null and next_id<>0 and next_id<>previous_id then
    raise exception 'commusoft_cursor_invalid' using errcode='22023';end if;
  if has_more then next_cp:=jsonb_set(next_cp,'{after}',to_jsonb(next_id));end if;
  if target is not null then
   next_cp:=next_cp||jsonb_build_object('propertyId',case when has_more then target->'propertyId' else target->'nextPropertyId' end,
    'propertiesCompleted',(target->>'position')::integer-case when has_more then 1 else 0 end,
    'complete',not has_more and target->'nextPropertyId'='null'::jsonb);
  end if;
  insert into public.learn_business_input_pages(id,tenant_id,connection_id,provider,collection,job_id,permit_id,envelope,checkpoint_before,checkpoint_after,record_count)
    values(page_id,p_tenant_id,connection.id,'commusoft',b->'request'->>'resource',p_job_id,p_permit_id,p_envelope,cp,next_cp,n);
  n:=0;
  for item in select value from jsonb_array_elements(p_envelope->'data') loop
    n:=n+1; v_hash:=encode(sha256(convert_to(item::text,'UTF8')),'hex');
    insert into public.learn_business_input_versions(tenant_id,connection_id,provider,collection,external_id,content_hash,payload)
      values(p_tenant_id,connection.id,'commusoft',b->'request'->>'resource',item->>'id',v_hash,item)
      on conflict(tenant_id,connection_id,provider,collection,external_id,content_hash) do nothing;
    select v.id,v.payload into version_id,saved_payload from public.learn_business_input_versions v where v.tenant_id=p_tenant_id
      and v.connection_id=connection.id and v.provider='commusoft' and v.collection=b->'request'->>'resource'
      and v.external_id=item->>'id' and v.content_hash=v_hash;
    if version_id is null or saved_payload is distinct from item then raise exception 'commusoft_version_conflict' using errcode='PT409';end if;
    insert into public.learn_business_input_observations values(page_id,version_id,n);
  end loop;
  if j.lease_expires_at<=clock_timestamp() or (cfg->>'expiresAt')::timestamptz<=clock_timestamp() then
    raise exception 'commusoft_authority_expired' using errcode='42501';end if;
  update public.connector_accounts set sync_cursor=next_cp where id=a.id and tenant_id=p_tenant_id;
  receipt:=jsonb_build_object('pageId',page_id,'checkpoint',next_cp,'records',n,'already',false);
  update public.platform_jobs set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('commusoft_page_v1',receipt) where id=j.id;
  return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.learn_commusoft_committed_page(p_tenant_id uuid, p_job_id uuid, p_claimed_by text, p_attempt_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;p public.learn_business_input_pages%rowtype;begin
  if auth.role() is distinct from 'service_role' then raise exception 'commusoft_receipt_forbidden' using errcode='42501';end if;
  select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for share;
  if not found or j.job_type is distinct from 'commusoft.source_sync' or j.status is distinct from 'running'
    or p_claimed_by is null or j.claimed_by is distinct from p_claimed_by or p_attempt_count is null
    or j.attempt_count is distinct from p_attempt_count or coalesce(j.lease_expires_at,'-infinity')<=clock_timestamp() then
    raise exception 'commusoft_job_unavailable' using errcode='42501';end if;
  select * into p from public.learn_business_input_pages where job_id=p_job_id and tenant_id=p_tenant_id;
  if not found then
    if coalesce(j.metadata,'{}'::jsonb) ? 'commusoft_page_v1' then raise exception 'commusoft_receipt_missing' using errcode='PT409';end if;
    return null;
  end if;
  if j.metadata->'commusoft_page_v1' is distinct from jsonb_build_object('pageId',p.id,'checkpoint',p.checkpoint_after,'records',p.record_count,'already',false) then
    raise exception 'commusoft_receipt_mismatch' using errcode='PT409';end if;
  return jsonb_build_object('pageId',p.id,'checkpoint',p.checkpoint_after,'records',p.record_count,'already',true);
end $function$

CREATE OR REPLACE FUNCTION public.learn_commusoft_contact_target(p_tenant uuid, p_connection uuid, p_cfg jsonb, p_cp jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare t public.learn_commusoft_contact_targets%rowtype;prop bigint;done integer;total integer;
begin
 if p_cfg->>'resource' is distinct from 'propertyContacts' or p_cfg->>'contactPlanVersion' is distinct from '1'
  or coalesce(p_cfg->>'contactType','') not in ('customer','workaddress')
  or jsonb_typeof(p_cfg->'contactTargetCount') is distinct from 'number'
  or coalesce(p_cfg->>'contactTargetCount','')!~'^[1-9][0-9]{0,8}$'
  or jsonb_typeof(p_cfg->'firstPropertyId') is distinct from 'number'
  or coalesce(p_cfg->>'firstPropertyId','')!~'^[1-9][0-9]{0,15}$' then return null;end if;
 total:=(p_cfg->>'contactTargetCount')::integer;
 if p_cp='{}'::jsonb then prop:=(p_cfg->>'firstPropertyId')::bigint;done:=0;
 else
  if p_cp->>'approvalId' is distinct from p_cfg->>'approvalId' or p_cp->'complete' is distinct from 'false'::jsonb
   or jsonb_typeof(p_cp->'propertyId') is distinct from 'number' or coalesce(p_cp->>'propertyId','')!~'^[1-9][0-9]{0,15}$'
   or jsonb_typeof(p_cp->'propertiesCompleted') is distinct from 'number' or coalesce(p_cp->>'propertiesCompleted','')!~'^[0-9]{1,9}$' then return null;end if;
  prop:=(p_cp->>'propertyId')::bigint;done:=(p_cp->>'propertiesCompleted')::integer;
 end if;
 select * into t from public.learn_commusoft_contact_targets where tenant_id=p_tenant and connection_id=p_connection
  and approval_id=(p_cfg->>'approvalId')::uuid and property_id=prop;
 if not found or t.property_type is distinct from p_cfg->>'contactType' or t.position<>done+1 or done>=total
  or (t.next_property_id is null) is distinct from (t.position=total) then return null;end if;
 return jsonb_build_object('propertyId',t.property_id,'nextPropertyId',t.next_property_id,'position',t.position,'total',total);
end $function$

CREATE OR REPLACE FUNCTION public.learn_commusoft_finish_job(p_tenant_id uuid, p_job_id uuid, p_claimed_by text, p_attempt_count integer, p_outcome jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j public.platform_jobs%rowtype;p public.learn_business_input_pages%rowtype;
 permit public.learn_business_input_request_permits%rowtype;a public.connector_accounts%rowtype;
 b jsonb;cfg jsonb;finish jsonb;receipt jsonb;answer jsonb;successor uuid;
 next_status text;stop_reason text;delay_seconds integer;failure_code text;allowed boolean;next_at timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'commusoft_queue_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' or p_claimed_by is null or p_attempt_count is null or p_attempt_count<1
   or jsonb_typeof(p_outcome) is distinct from 'object' or jsonb_typeof(p_outcome->'success') is distinct from 'boolean' then
   raise exception 'commusoft_queue_invalid' using errcode='22023';end if;
 select * into j from public.platform_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
 if not found or j.job_type is distinct from 'commusoft.source_sync' or j.claimed_by is distinct from p_claimed_by or j.attempt_count is distinct from p_attempt_count then
   raise exception 'commusoft_queue_not_owned' using errcode='PT409';end if;
 finish:=j.metadata->'commusoft_finish_v1';
 if j.status in ('succeeded','retrying','dead_letter') and finish->>'claimed_by'=p_claimed_by and (finish->>'attempt_count')::integer=p_attempt_count then
   if finish->'outcome'=p_outcome then return finish->'answer';end if;
   raise exception 'commusoft_queue_replay_conflict' using errcode='PT409';
 end if;
 if j.status is distinct from 'running' or coalesce(j.lease_expires_at,'-infinity')<=clock_timestamp() then
   raise exception 'commusoft_queue_not_owned' using errcode='PT409';end if;
 select * into p from public.learn_business_input_pages where job_id=j.id and tenant_id=p_tenant_id;
 if found then
   -- Never overwrite a committed page as failed, including a lost publication reply.
   if p_outcome<>'{"success":true}'::jsonb then raise exception 'commusoft_queue_page_committed' using errcode='PT409';end if;
   receipt:=jsonb_build_object('pageId',p.id,'checkpoint',p.checkpoint_after,'records',p.record_count,'already',false);
   if j.metadata->'commusoft_page_v1' is distinct from receipt then raise exception 'commusoft_queue_receipt_mismatch' using errcode='PT409';end if;
   select * into permit from public.learn_business_input_request_permits where id=p.permit_id;
   if not found then raise exception 'commusoft_queue_receipt_mismatch' using errcode='PT409';end if;
   b:=permit.binding;cfg:=b->'approval';
   if j.job_key is distinct from 'commusoft.source:'||(b->>'accountId')||':'||(cfg->>'approvalId') then
     raise exception 'commusoft_queue_identity' using errcode='PT409';end if;
   stop_reason:=case when p.checkpoint_after->'complete'='true'::jsonb then 'collection_exhausted'
     when (p.checkpoint_after->>'pages')::integer>=(cfg->>'maxPages')::integer then 'page_budget_exhausted' else 'next_page' end;
   if stop_reason='next_page' then
     -- Current switches/approval decide only whether to continue. Prior committed
     -- work is still acknowledged if an operator has since disabled processing.
     perform 1 from public.tenants where id=p_tenant_id and status='active' for share;
     allowed:=found;
     perform 1 from public.feature_flags where tenant_id=p_tenant_id and flag='learn.enabled' and value='true'::jsonb for share;
     allowed:=allowed and found;
     perform 1 from public.feature_flags where tenant_id=p_tenant_id and flag='learn.inputs.commusoft.enabled' and value='true'::jsonb for share;
     allowed:=allowed and found;
     select * into a from public.connector_accounts where id::text=b->>'accountId' and tenant_id=p_tenant_id for share;
     allowed:=allowed and found and a.status='active' and a.settings->'commusoft_import'=cfg and a.sync_cursor=p.checkpoint_after
       and coalesce((cfg->>'expiresAt')::timestamptz,'-infinity')>clock_timestamp();
     perform 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant_id and connector_id='commusoft'
       and provider='commusoft' and enabled and status='active' for share;
     allowed:=allowed and found;
     perform 1 from public.provider_connections where id::text=b->>'connectionId' and tenant_id=p_tenant_id
       and provider='commusoft' and status='configured' and auth_mode='private_api_key' and revoked_at is null and verified_at is not null
       and verified_at<=clock_timestamp() and updated_at=(b->>'connectionRevision')::timestamptz
       and non_secret_config->>'account_key'=a.account_key and non_secret_config->>'region'=b->'request'->>'region'
       and secret_refs->>'api_key'=b->>'secretId' and 'api_key'=any(configured_fields) for share;
     allowed:=allowed and found;
     if allowed is distinct from true then stop_reason:='authorisation_changed';end if;
   end if;
   update public.platform_jobs set status='succeeded',completed_at=clock_timestamp(),lease_expires_at=null,error_code=null,
     records_processed=p.record_count,result=jsonb_build_object('receipt',receipt,'stop_reason',stop_reason,
       'coverage','one_collection_traversal','ingestion_complete',false) where id=j.id;
   if stop_reason='next_page' then
     select next_allowed_at into next_at from public.learn_business_input_request_gates
       where credential_fingerprint=permit.credential_fingerprint for share;
     if not found then raise exception 'commusoft_queue_gate_missing' using errcode='PT409';end if;
     insert into public.platform_jobs(tenant_id,connector_id,module_id,job_type,job_key,status,priority,max_attempts,available_at,parent_job_id,payload)
       values(p_tenant_id,j.connector_id,j.module_id,j.job_type,j.job_key,'queued',j.priority,j.max_attempts,
         greatest(clock_timestamp()+interval '1250 milliseconds',next_at),j.id,jsonb_build_object('connector_account_id',a.id)) returning id into successor;
   end if;
   next_status:='succeeded';
 else
   if coalesce(j.metadata,'{}'::jsonb) ? 'commusoft_page_v1' then raise exception 'commusoft_queue_receipt_mismatch' using errcode='PT409';end if;
   if p_outcome->'success'='true'::jsonb then raise exception 'commusoft_queue_page_missing' using errcode='PT409';end if;
   if not p_outcome ?& array['success','code','retryable','retry_after_seconds'] or (select count(*) from jsonb_object_keys(p_outcome))<>4
     or jsonb_typeof(p_outcome->'retryable') is distinct from 'boolean' or jsonb_typeof(p_outcome->'code') is distinct from 'string'
     or p_outcome->>'code' !~ '^commusoft_[a-z_]{1,80}$' or jsonb_typeof(p_outcome->'retry_after_seconds') is distinct from 'number'
     or p_outcome->>'retry_after_seconds' !~ '^[0-9]{1,8}$' then raise exception 'commusoft_queue_invalid' using errcode='22023';end if;
   delay_seconds:=(p_outcome->>'retry_after_seconds')::integer;
   if delay_seconds>31536000 then raise exception 'commusoft_queue_invalid' using errcode='22023';end if;
   delay_seconds:=greatest(delay_seconds,case j.attempt_count when 1 then 60 when 2 then 300 when 3 then 900 else 3600 end);
   next_status:=case when p_outcome->'retryable'='true'::jsonb and j.attempt_count<j.max_attempts then 'retrying' else 'dead_letter' end;
   failure_code:=p_outcome->>'code';
   update public.platform_jobs set status=next_status,lease_expires_at=null,error_code=failure_code,error_count=coalesce(error_count,0)+1,
     failed_at=clock_timestamp(),available_at=case when next_status='retrying' then clock_timestamp()+make_interval(secs=>delay_seconds) else available_at end,
     dead_lettered_at=case when next_status='dead_letter' then clock_timestamp() else dead_lettered_at end where id=j.id;
 end if;
 if j.lease_expires_at<=clock_timestamp() then raise exception 'commusoft_queue_not_owned' using errcode='PT409';end if;
 answer:=jsonb_build_object('job_id',j.id,'status',next_status,'successor_id',successor);
 update public.platform_jobs set metadata=coalesce(metadata,'{}')||jsonb_build_object('commusoft_finish_v1',
   jsonb_build_object('claimed_by',p_claimed_by,'attempt_count',p_attempt_count,'outcome',p_outcome,'answer',answer)) where id=j.id;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION public.learn_operator_input_request(p_tenant uuid, p_request uuid, p_actor uuid, p_definition jsonb, p_mode text DEFAULT 'apply'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare prior public.learn_operator_input_requests%rowtype;c public.provider_connections%rowtype;
 tc public.tenant_connectors%rowtype;a public.connector_accounts%rowtype;
 receipt jsonb;previous jsonb;scope jsonb;flags jsonb;kind text;reason text;k text;
 connection_id uuid;revision timestamptz;expiry timestamptz;resource text;contact_type text;
 pages integer;page_size integer;aid uuid;jid uuid:=gen_random_uuid();
 property_approval uuid;target_count integer;first_property bigint;
begin
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 if p_request is null or p_mode is null or p_mode not in ('apply','check','cancel')
  or jsonb_typeof(p_definition) is distinct from 'object' or octet_length(p_definition::text)>10000 then
  raise exception 'learn_operator_request_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-input-request:'||p_request::text,0));
 select * into prior from public.learn_operator_input_requests where id=p_request;
 if found then
  if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.definition<>p_definition then
   raise exception 'learn_operator_request_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if p_mode='check' then return jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','pending');end if;
 if p_mode='cancel' then
  receipt:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','cancelled');
  insert into public.learn_operator_input_requests(id,tenant_id,actor_id,definition,receipt)
   values(p_request,p_tenant,p_actor,p_definition,receipt);
  return receipt;
 end if;
 kind:=p_definition->>'kind';reason:=p_definition->>'reason';
 if jsonb_typeof(p_definition->'reason') is distinct from 'string' or length(btrim(reason)) not between 1 and 1000
  or kind is null or kind not in ('set_modules','start_commusoft') then raise exception 'learn_operator_definition_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 if kind='set_modules' then
  if (select count(*) from jsonb_object_keys(p_definition))<>4
   or jsonb_typeof(p_definition->'expected') is distinct from 'object'
   or jsonb_typeof(p_definition->'values') is distinct from 'object'
   or (select count(*) from jsonb_object_keys(p_definition->'values'))<>2
   or jsonb_typeof(p_definition->'values'->'learn.enabled') is distinct from 'boolean'
   or jsonb_typeof(p_definition->'values'->'learn.inputs.commusoft.enabled') is distinct from 'boolean' then
   raise exception 'learn_operator_flags_invalid' using errcode='22023';end if;
  perform 1 from public.feature_flags where tenant_id=p_tenant and flag in ('learn.enabled','learn.inputs.commusoft.enabled') order by flag for update;
  flags:=public.learn_operator_input_flags(p_tenant);
  if flags is distinct from p_definition->'expected' then raise exception 'learn_operator_flags_changed' using errcode='PT409';end if;
  previous:=flags;
  foreach k in array array['learn.enabled','learn.inputs.commusoft.enabled'] loop
   update public.feature_flags set value=p_definition->'values'->k where tenant_id=p_tenant and flag=k;
   if not found then insert into public.feature_flags(tenant_id,flag,value) values(p_tenant,k,p_definition->'values'->k);end if;
  end loop;
  receipt:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','recorded','kind',kind,'flags',p_definition->'values');
 else
  if not p_definition ?& array['kind','reason','connection_id','revision','resource','max_pages','page_size','expires_at']
   or (p_definition-array['kind','reason','connection_id','revision','resource','contact_type','max_pages','page_size','expires_at'])<>'{}'::jsonb
   or jsonb_typeof(p_definition->'connection_id') is distinct from 'string'
   or p_definition->>'connection_id'!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(p_definition->'max_pages') is distinct from 'number' or p_definition->>'max_pages'!~'^[0-9]{1,5}$'
   or jsonb_typeof(p_definition->'page_size') is distinct from 'number' or p_definition->>'page_size'!~'^[0-9]{1,3}$'
   or jsonb_typeof(p_definition->'revision') is distinct from 'string'
   or jsonb_typeof(p_definition->'expires_at') is distinct from 'string' then raise exception 'learn_operator_import_invalid' using errcode='22023';end if;
  connection_id:=(p_definition->>'connection_id')::uuid;revision:=(p_definition->>'revision')::timestamptz;
  expiry:=(p_definition->>'expires_at')::timestamptz;resource:=p_definition->>'resource';contact_type:=p_definition->>'contact_type';
  pages:=(p_definition->>'max_pages')::integer;page_size:=(p_definition->>'page_size')::integer;
  if not isfinite(revision) or not isfinite(expiry) or expiry<=clock_timestamp() or expiry>clock_timestamp()+interval '24 hours'
   or pages not between 1 and 10000 or page_size not between 1 and 100 or resource is null or resource not in ('properties','propertyContacts','jobs')
   or (resource='propertyContacts' and (contact_type is null or contact_type not in ('customer','workaddress')))
   or (resource<>'propertyContacts' and p_definition ? 'contact_type') then raise exception 'learn_operator_import_invalid' using errcode='22023';end if;
  perform 1 from public.tenants where id=p_tenant and status='active';
  if not found then raise exception 'learn_operator_tenant_inactive' using errcode='55000';end if;
  foreach k in array array['learn.enabled','learn.inputs.commusoft.enabled'] loop
   perform 1 from public.feature_flags where tenant_id=p_tenant and flag=k and value='true'::jsonb for share;
   if not found then raise exception 'learn_operator_module_disabled' using errcode='55000';end if;
  end loop;
  select * into c from public.provider_connections where id=connection_id and tenant_id=p_tenant for share;
  if not found or c.provider is distinct from 'commusoft' or c.status is distinct from 'configured' or c.auth_mode is distinct from 'private_api_key'
   or c.revoked_at is not null or c.verified_at is null or c.verified_at>clock_timestamp() or c.updated_at is distinct from revision
   or coalesce(c.non_secret_config->>'region','') not in ('uk','us')
   or length(btrim(coalesce(c.non_secret_config->>'account_key',''))) not between 1 and 2000
   or not coalesce('api_key'=any(c.configured_fields),false)
   or coalesce(c.secret_refs->>'api_key','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
   raise exception 'learn_operator_connection_changed' using errcode='PT409';end if;
  -- Existence only: the setup surface never selects a secret value. The worker
  -- still revalidates the tenant-qualified secret and all authority at acquisition.
  perform 1 from vault.secrets where id=(c.secret_refs->>'api_key')::uuid and name='provider_secret:'||p_tenant::text||':commusoft:api_key';
  if not found then raise exception 'learn_operator_credential_missing' using errcode='55000';end if;
  select * into tc from public.tenant_connectors where tenant_id=p_tenant and connector_id='commusoft' for update;
  if not found then
   insert into public.tenant_connectors(tenant_id,connector_id,provider,category,status,enabled)
    values(p_tenant,'commusoft','commusoft','business_input','active',true) returning * into tc;
  elsif tc.provider is distinct from 'commusoft' or tc.enabled is distinct from true or tc.status is distinct from 'active' then
   raise exception 'learn_operator_connector_disabled' using errcode='55000';
  end if;
  select * into a from public.connector_accounts where tenant_id=p_tenant and tenant_connector_id=tc.id and account_key=c.non_secret_config->>'account_key' for update;
  if found then
   if a.status is distinct from 'active' or exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='commusoft.source_sync'
    and payload->>'connector_account_id'=a.id::text and status in ('queued','running','retrying')) then
    raise exception 'learn_operator_import_active' using errcode='55000';end if;
   if a.settings ? 'commusoft_import' and (a.sync_cursor->'complete' is distinct from 'true'::jsonb
    or a.sync_cursor->>'approvalId' is distinct from a.settings->'commusoft_import'->>'approvalId') then
    raise exception 'learn_operator_import_incomplete' using errcode='55000';end if;
   if a.settings ? 'commusoft_import' and a.settings->'commusoft_import'->>'connectionId' is distinct from c.id::text then
    raise exception 'learn_operator_account_connection_changed' using errcode='PT409';end if;
   previous:=jsonb_build_object('approval',a.settings->'commusoft_import','checkpoint',a.sync_cursor);aid:=a.id;
  else
   insert into public.connector_accounts(tenant_id,tenant_connector_id,account_key,display_name,status)
    values(p_tenant,tc.id,c.non_secret_config->>'account_key','Commusoft','active') returning id into aid;
  end if;
  scope:=jsonb_build_object('approved',true,'approvalId',p_request,'connectionId',c.id,'consentReference','learn-operator-input:'||p_request::text,
   'expiresAt',expiry,'maxPages',pages,'pageSize',page_size,'resource',resource)
   ||case when resource='propertyContacts' then jsonb_build_object('contactType',contact_type) else '{}'::jsonb end;
  if resource='propertyContacts' then
   -- Use the last completed property traversal, not the mutable newest union of
   -- source versions. Account/connection locks serialize approvals and imports.
   select (p.checkpoint_after->>'approvalId')::uuid into property_approval
    from public.learn_business_input_pages p where p.tenant_id=p_tenant and p.connection_id=c.id
     and p.provider='commusoft' and p.collection='properties' and p.checkpoint_after->'complete'='true'::jsonb
    order by p.committed_at desc,p.id desc limit 1;
   if property_approval is null then raise exception 'learn_operator_property_traversal_required' using errcode='55000';end if;
   with observed as (
    select distinct on(v.external_id) v.id,v.payload,v.external_id
     from public.learn_business_input_pages p
     join public.learn_business_input_observations o on o.page_id=p.id
     join public.learn_business_input_versions v on v.id=o.version_id and v.tenant_id=p.tenant_id
      and v.connection_id=p.connection_id and v.provider=p.provider and v.collection=p.collection
     where p.tenant_id=p_tenant and p.connection_id=c.id and p.provider='commusoft' and p.collection='properties'
      and p.checkpoint_after->>'approvalId'=property_approval::text
     order by v.external_id,(p.checkpoint_after->>'pages')::integer desc
   ), chosen as (
    select id,(payload->>'id')::bigint as property_id from observed
     where payload->>'type'=contact_type and jsonb_typeof(payload->'id')='number'
      and payload->>'id'~'^[1-9][0-9]{0,15}$' and payload->>'id'=external_id
   ) insert into public.learn_commusoft_contact_targets(tenant_id,connection_id,approval_id,property_id,property_type,source_version_id,position,next_property_id)
    select p_tenant,c.id,p_request,property_id,contact_type,id,row_number() over(order by property_id),lead(property_id) over(order by property_id)
    from chosen where property_id<=9007199254740991;
   select count(*)::integer,min(t.property_id) into target_count,first_property from public.learn_commusoft_contact_targets t
    where t.tenant_id=p_tenant and t.connection_id=c.id and t.approval_id=p_request;
   if target_count=0 then raise exception 'learn_operator_contact_properties_missing' using errcode='55000';end if;
   scope:=scope||jsonb_build_object('contactPlanVersion',1,'contactTargetCount',target_count,'firstPropertyId',first_property,'propertyTraversalApprovalId',property_approval);
  end if;
  update public.connector_accounts set settings=settings||jsonb_build_object('commusoft_import',scope),sync_cursor='{}' where id=aid;
  insert into public.platform_jobs(id,tenant_id,connector_id,module_id,job_type,job_key,status,max_attempts,available_at,payload,created_by)
   values(jid,p_tenant,'commusoft','learn','commusoft.source_sync','commusoft.source:'||aid::text||':'||p_request::text,'queued',5,clock_timestamp(),jsonb_build_object('connector_account_id',aid),p_actor);
  receipt:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','recorded','kind',kind,'account_id',aid,'job_id',jid);
 end if;
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 insert into public.learn_operator_input_requests(id,tenant_id,actor_id,definition,receipt,previous_state)
  values(p_request,p_tenant,p_actor,p_definition,receipt,previous);
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.learn_operator_resume_commusoft(p_tenant uuid, p_request uuid, p_actor uuid, p_definition jsonb, p_mode text DEFAULT 'apply'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare prior public.learn_operator_input_requests%rowtype;a public.connector_accounts%rowtype;
 c public.provider_connections%rowtype;tc public.tenant_connectors%rowtype;j public.platform_jobs%rowtype;
 cfg jsonb;cp jsonb;observed jsonb;receipt jsonb;previous jsonb;k text;
 expiry timestamptz;revision timestamptz;pages integer;retained integer;jid uuid:=gen_random_uuid();
begin
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 if p_request is null or p_mode is null or p_mode not in ('apply','check','cancel')
  or jsonb_typeof(p_definition) is distinct from 'object' or octet_length(p_definition::text)>10000 then
  raise exception 'learn_operator_request_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-input-request:'||p_request::text,0));
 select * into prior from public.learn_operator_input_requests where id=p_request;
 if found then
  if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.definition<>p_definition then
   raise exception 'learn_operator_request_conflict' using errcode='PT409';end if;
  return prior.receipt;
 end if;
 if p_mode='check' then return jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','pending');end if;
 if p_mode='cancel' then
  receipt:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','cancelled');
  insert into public.learn_operator_input_requests(id,tenant_id,actor_id,definition,receipt)
   values(p_request,p_tenant,p_actor,p_definition,receipt);
  return receipt;
 end if;
 if p_definition->>'kind' is distinct from 'resume_commusoft'
  or not p_definition ?& array['kind','reason','account_id','approval_id','job_id','connection_id','revision','checkpoint','max_pages','expires_at']
  or (select count(*) from jsonb_object_keys(p_definition))<>10
  or jsonb_typeof(p_definition->'reason') is distinct from 'string' or length(btrim(p_definition->>'reason')) not between 1 and 1000
  or jsonb_typeof(p_definition->'revision') is distinct from 'string'
  or jsonb_typeof(p_definition->'expires_at') is distinct from 'string'
  or jsonb_typeof(p_definition->'checkpoint') is distinct from 'object'
  or jsonb_typeof(p_definition->'max_pages') is distinct from 'number' or p_definition->>'max_pages'!~'^[0-9]{1,10}$' then
  raise exception 'learn_operator_resume_invalid' using errcode='22023';end if;
 foreach k in array array['account_id','approval_id','job_id','connection_id'] loop
  if jsonb_typeof(p_definition->k) is distinct from 'string' or p_definition->>k!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
   raise exception 'learn_operator_resume_invalid' using errcode='22023';end if;
 end loop;
 expiry:=(p_definition->>'expires_at')::timestamptz;revision:=(p_definition->>'revision')::timestamptz;pages:=(p_definition->>'max_pages')::integer;
 if not isfinite(expiry) or not isfinite(revision) or expiry<=clock_timestamp() or expiry>clock_timestamp()+interval '24 hours' or pages not between 1 and 2147483647 then
  raise exception 'learn_operator_resume_invalid' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('learn-input-setup:'||p_tenant::text,0));
 perform 1 from public.tenants where id=p_tenant and status='active';
 if not found then raise exception 'learn_operator_tenant_inactive' using errcode='55000';end if;
 foreach k in array array['learn.enabled','learn.inputs.commusoft.enabled'] loop
  perform 1 from public.feature_flags where tenant_id=p_tenant and flag=k and value='true'::jsonb for share;
  if not found then raise exception 'learn_operator_module_disabled' using errcode='55000';end if;
 end loop;
 select * into c from public.provider_connections where id=(p_definition->>'connection_id')::uuid and tenant_id=p_tenant for share;
 if not found or c.provider is distinct from 'commusoft' or c.status is distinct from 'configured' or c.auth_mode is distinct from 'private_api_key'
  or c.revoked_at is not null or c.verified_at is null or c.verified_at>clock_timestamp() or c.updated_at is distinct from revision
  or coalesce(c.non_secret_config->>'region','') not in ('uk','us')
  or not coalesce('api_key'=any(c.configured_fields),false)
  or coalesce(c.secret_refs->>'api_key','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'learn_operator_connection_changed' using errcode='PT409';end if;
 perform 1 from vault.secrets where id=(c.secret_refs->>'api_key')::uuid and name='provider_secret:'||p_tenant::text||':commusoft:api_key';
 if not found then raise exception 'learn_operator_credential_missing' using errcode='55000';end if;
 select * into tc from public.tenant_connectors where tenant_id=p_tenant and connector_id='commusoft' for update;
 if not found or tc.provider is distinct from 'commusoft' or tc.enabled is distinct from true or tc.status is distinct from 'active' then
  raise exception 'learn_operator_connector_disabled' using errcode='55000';end if;
 select * into a from public.connector_accounts where id=(p_definition->>'account_id')::uuid and tenant_id=p_tenant and tenant_connector_id=tc.id for update;
 if not found or a.status is distinct from 'active' or a.account_key is distinct from c.non_secret_config->>'account_key' then
  raise exception 'learn_operator_account_changed' using errcode='PT409';end if;
 cfg:=a.settings->'commusoft_import';cp:=a.sync_cursor;
 observed:=jsonb_build_object('approvalId',cp->'approvalId','pages',cp->'pages','after',cp->'after','complete',cp->'complete');
 if cp ? 'propertyId' then observed:=observed||jsonb_build_object('propertyId',cp->'propertyId','propertiesCompleted',cp->'propertiesCompleted');end if;
 if cfg->'approved' is distinct from 'true'::jsonb or cfg->>'approvalId' is distinct from p_definition->>'approval_id'
  or cfg->>'connectionId' is distinct from c.id::text or observed is distinct from p_definition->'checkpoint'
  or jsonb_typeof(cfg->'maxPages') is distinct from 'number' or coalesce(cfg->>'maxPages','')!~'^[0-9]{1,10}$'
  or jsonb_typeof(cfg->'expiresAt') is distinct from 'string'
  or coalesce(cfg->>'resource','') not in ('properties','jobs','propertyContacts')
  or (cfg->>'resource'='propertyContacts' and coalesce(cfg->>'contactType','') not in ('customer','workaddress')) then
  raise exception 'learn_operator_progress_changed' using errcode='PT409';end if;
 if cfg->>'resource'='propertyContacts' and public.learn_commusoft_contact_target(p_tenant,c.id,cfg,cp) is null then
  raise exception 'learn_operator_contact_plan_invalid' using errcode='PT409';end if;
 -- No active attempt is reset or displaced, even after its lease expires.
 if exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='commusoft.source_sync'
  and payload->>'connector_account_id'=a.id::text and status in ('queued','running','retrying')) then
  raise exception 'learn_operator_import_active' using errcode='55000';end if;
 select * into j from public.platform_jobs where tenant_id=p_tenant and job_type='commusoft.source_sync'
  and payload->>'connector_account_id'=a.id::text order by created_at desc,id desc limit 1 for update;
 if not found or j.id::text is distinct from p_definition->>'job_id' or j.status not in ('succeeded','dead_letter')
  or j.job_key is distinct from 'commusoft.source:'||a.id::text||':'||(cfg->>'approvalId')
  or coalesce(j.lease_expires_at,'-infinity')>clock_timestamp() then
  raise exception 'learn_operator_progress_changed' using errcode='PT409';end if;
 -- Committed but unsettled work must go through source-free worker recovery.
 if j.status='dead_letter' and (j.metadata ? 'commusoft_page_v1' or exists(select 1 from public.learn_business_input_pages where job_id=j.id)) then
  raise exception 'learn_operator_page_unsettled' using errcode='55000';end if;
 if j.status='succeeded' and not exists(select 1 from public.learn_business_input_pages where job_id=j.id and tenant_id=p_tenant
  and connection_id=c.id and provider='commusoft' and collection=cfg->>'resource' and checkpoint_after=cp) then
  raise exception 'learn_operator_checkpoint_invalid' using errcode='PT409';end if;
 if cp='{}'::jsonb then
  retained:=0;
  if j.status='succeeded' or exists(select 1 from public.learn_business_input_pages where tenant_id=p_tenant and connection_id=c.id and checkpoint_after->>'approvalId'=cfg->>'approvalId') then
   raise exception 'learn_operator_checkpoint_invalid' using errcode='PT409';end if;
 else
  if cp->>'approvalId' is distinct from cfg->>'approvalId' or cp->'complete' is distinct from 'false'::jsonb
   or jsonb_typeof(cp->'pages') is distinct from 'number' or cp->>'pages'!~'^[0-9]{1,10}$' then
   raise exception 'learn_operator_checkpoint_invalid' using errcode='PT409';end if;
  retained:=(cp->>'pages')::integer;
  -- Require the exact last retained page, not a cursor supplied by the browser.
  select checkpoint_after into observed from public.learn_business_input_pages where tenant_id=p_tenant and connection_id=c.id
   and provider='commusoft' and collection=cfg->>'resource' and checkpoint_after->>'approvalId'=cfg->>'approvalId'
   order by (checkpoint_after->>'pages')::integer desc limit 1;
  if not found or observed is distinct from cp or retained<1 then raise exception 'learn_operator_checkpoint_invalid' using errcode='PT409';end if;
 end if;
 if pages<=retained or pages::bigint-retained>10000 or pages<(cfg->>'maxPages')::integer or expiry<(cfg->>'expiresAt')::timestamptz then
  raise exception 'learn_operator_resume_limits' using errcode='22023';end if;
 previous:=jsonb_build_object('approval',cfg,'checkpoint',cp,'job_id',j.id,'job_status',j.status);
 cfg:=cfg||jsonb_build_object('expiresAt',expiry,'maxPages',pages);
 update public.connector_accounts set settings=settings||jsonb_build_object('commusoft_import',cfg) where id=a.id;
 insert into public.platform_jobs(id,tenant_id,connector_id,module_id,job_type,job_key,status,max_attempts,available_at,parent_job_id,payload,created_by)
  values(jid,p_tenant,'commusoft','learn','commusoft.source_sync',j.job_key,'queued',5,clock_timestamp(),j.id,jsonb_build_object('connector_account_id',a.id),p_actor);
 receipt:=jsonb_build_object('tenant_id',p_tenant,'request_id',p_request,'state','recorded','kind','resume_commusoft','account_id',a.id,'job_id',jid,'approval_id',cfg->>'approvalId','checkpoint',p_definition->'checkpoint');
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 insert into public.learn_operator_input_requests(id,tenant_id,actor_id,definition,receipt,previous_state) values(p_request,p_tenant,p_actor,p_definition,receipt,previous);
 return receipt;
end $function$

